import { Book } from "@/lib/types";

export const _2samuel: Book = {
  id: "2samuel",
  name: "2. Samuel",
  shortName: "2Sam",
  testament: "old",
  introduction: `David, der Herrscher Israels\n**Das zweite Buch Samuel**, das ursprünglich mit dem ersten eine Einheit bildete, berichtet zunächst, wie David König über ganz Israel wurde und die Bundeslade nach Jerusalem brachte. Das Buch zeigt dann, wie das Königtum Davids sich im Aufstand seines Sohnes Abschalom bewährte und schließt mit dem Kauf eines Platzes zum Dreschen von Getreide, an dessen Stelle später der Tempel gebaut wurde.\n****Wie David an die Macht in Israel kommt und wie er seine Krisen durchsteht.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Als David nach dem Tod Sauls von seinem Sieg über die Amalekiter* zurückgekehrt war, hielt er sich zwei Tage lang in Ziklag* auf.", heading: "1-10: Davids Sieg über alle Feinde\nDavid Herrschaft über Juda (1-4)\nDavid erfährt von Sauls und Jonatans Tod", footnotes: ["Die Amalekiter lebten als Nomaden im Negev, südlich von Beerscheba.", "Ziklag. Stadt im Gebiet der Philister (1. Samuel 27,6)."] },
      { number: 2, text: "Am dritten Tag kam einer von Sauls Leuten aus dem Heerlager. Seine Kleidung war zerrissen und er hatte Erde auf dem Kopf.* Als er zu David kam, warf er sich ehrfürchtig auf den Boden vor ihn.", footnotes: ["Kleider ... Kopf. Das waren Zeichen von Trauer und Entsetzen."] },
      { number: 3, text: "\"Wo kommst du her?\", fragte ihn David. \"Ich habe mich aus dem Heerlager Israels in Sicherheit gebracht\", erwiderte er." },
      { number: 4, text: "\"Wie steht es?\", fragte David. \"Berichte es mir!\" Er sagte: \"Das ganze Heer wurde in die Flucht geschlagen, und viele sind gefallen. Auch Saul und sein Sohn Jonatan sind tot.\"" },
      { number: 5, text: "Da fragte David den jungen Mann: \"Saul und Jonatan sind tot? Woher weißt du das?\"" },
      { number: 6, text: "Der junge Mann berichtete: \"Ich geriet zufällig auf die Berge von Gilboa. Da sah ich Saul stehen, wie er sich auf seinen Speer stützte. Die Streitwagen hatten ihn schon fast erreicht." },
      { number: 7, text: "Da drehte er sich um, sah mich und rief mich zu sich. 'Ja, Herr', sagte ich." },
      { number: 8, text: "'Wer bist du?', fragte er. 'Ein Amalekiter', antwortete ich." },
      { number: 9, text: "Da sagte er zu mir: 'Komm her und gib mir den Todesstoß! Mit mir geht es zu Ende.'" },
      { number: 10, text: "Da trat ich zu ihm und gab ihm den Todesstoß, denn ich sah, dass er seinen Fall nicht überleben würde. Dann nahm ich ihm den Stirnreif und die Armspange ab. Hier sind sie, Herr.\"" },
      { number: 11, text: "Da riss David sein Obergewand ein.* Dasselbe taten auch die Männer, die bei ihm waren.", footnotes: ["riss ... ein. Als Zeichen von Trauer und Entsetzen riss man das entsprechende Kleidungsstück vom Halsausschnitt an mit einem heftigen Ruck etwa eine Handlänge ein."] },
      { number: 12, text: "Sie trauerten, weinten und fasteten bis zum Abend um Saul und seinen Sohn Jonatan, um das Volk Jahwes und die Männer Israels, die in der Schlacht gefallen waren." },
      { number: 13, text: "Dann fragte David den jungen Mann, der ihm das berichtet hatte: \"Woher stammst du?\" – \"Ich bin der Sohn eines amalekitischen Einwanderers\", erwiderte dieser." },
      { number: 14, text: "Da fuhr David ihn an: \"Wie konntest du es wagen, Jahwes gesalbten König anzutasten und ihn umzubringen?\"" },
      { number: 15, text: "Er rief einem seiner jungen Männer zu: \"Komm her und mach ihn nieder!\" Der ging hin und erschlug ihn." },
      { number: 16, text: "David sagte noch zu dem Amalekiter: \"Dein Blut komme auf dich selbst zurück! Du hast dir selbst das Urteil gesprochen, als du sagtest: 'Ich habe Jahwes gesalbtem König den Todesstoß gegeben.'\"" },
      { number: 17, text: "Dann stimmte David über Saul und dessen Sohn Jonatan die Totenklage an" },
      { number: 18, text: "und ordnete an, man solle es die Söhne Judas als Bogenlied lehren. Es ist im Buch der Heldenlieder* aufgenommen worden:", footnotes: ["Heldenlieder. Hebräisch: Buch Jaschar. Wörtlich: Buch des Redlichen, vermutlich eine Sammlung von Liedern auf die Helden Israels."] },
      { number: 19, text: "Die Zierde Israels liegt erschlagen auf deinen Höhen! / Wie sind die Helden gefallen!" },
      { number: 20, text: "Berichtet es nicht in Gat, / verkündet es nicht in Aschkelons Gassen, / sonst freuen sich die Töchter der Philister, / sonst jubeln die Töchter dieser Unbeschnittenen*.", footnotes: ["Unbeschnittene. Verächtlicher Ausdruck für Menschen, die nicht zum Bund Gottes gehörten. Siehe 1. Mose 17,9-14!"] },
      { number: 21, text: "Ihr Berge von Gilboa, / Felder des Todes, / kein Tau und kein Regen falle auf euch! / Denn dort wurde der Schild der Helden besudelt, / Sauls Schild, nicht mit Öl gesalbt, nein," },
      { number: 22, text: "mit dem Blut von Erschlagenen, / dem Körperfett von Helden. / Jonatans Bogen wich niemals zurück, / Sauls Schwert kehrte nie erfolglos heim!" },
      { number: 23, text: "Saul und Jonatan, / geliebt und liebenswert, solange sie lebten, / sind nun auch im Tod noch vereint. / Sie waren schneller als Adler / und stärker als Löwen." },
      { number: 24, text: "Ihr Töchter Israels, / um Saul müsst ihr weinen, / er hat euch in köstlichen Purpur gekleidet, / er heftete Goldschmuck an euer Gewand." },
      { number: 25, text: "Wie sind die Helden gefallen / mitten im Kampf! / Auch Jonatan / liegt tot auf deinen Bergen." },
      { number: 26, text: "Mein Bruder Jonatan, / es tut mir leid um dich! / Deine Freundschaft war mir viel mehr, / als Frauenliebe je bedeuten kann." },
      { number: 27, text: "Wie sind die Helden gefallen, / dahin die Waffen des Kampfes!" },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Bald danach fragte David Jahwe: \"Soll ich jetzt in eine der Städte Judas hinaufziehen?\" Jahwe sagte: \"Zieh hinauf!\" David fragte weiter: \"Wohin soll ich gehen?\" – \"Nach Hebron\", war die Antwort.", heading: "David wird König von Juda" },
      { number: 2, text: "Da zog David dort hinauf. Seine beiden Frauen Ahinoam aus Jesreel und Abigajil, die Witwe Nabals aus Karmel, nahm er mit." },
      { number: 3, text: "Auch seine Truppe ließ er samt ihren Familien mitziehen. Sie ließen sich in der Umgebung von Hebron nieder." },
      { number: 4, text: "Dann kamen die Männer des Stammes Juda und salbten David dort zu ihrem König.Als man David berichtete, dass die Männer von Jabesch in Gilead* Saul begraben* hätten,", footnotes: ["Gilead bezeichnet das mittlere, manchmal auch das ganze Ostjordanland.", "Saul begraben. 1. Samuel 31,11-13."] },
      { number: 5, text: "schickte er Boten dorthin und ließ ihnen sagen: \"Jahwe möge euch segnen, dass ihr Saul, eurem Herrn, die Liebe erwiesen habt, ihn zu begraben!" },
      { number: 6, text: "Jahwe erweise euch nun auch seine Liebe und Treue! Und ich will euch ebenfalls Gutes tun, weil ihr das getan habt." },
      { number: 7, text: "Nun zeigt euren Mut und seid tapfer, denn Saul, euer Herr, ist tot, und das Haus Juda hat mich zu seinem König gesalbt.* \"", footnotes: ["Juda hat mich ... gesalbt. Das war eine versteckte Einladung an die Leute von Jabesch, ihn als König anzuerkennen, was diese aber ignorierten."] },
      { number: 8, text: "Doch Abner Ben-Ner, Sauls Heerführer, hatte sich mit Isch-Boschet*, einem Sohn Sauls, nach Mahanajim* zurückgezogen.", heading: "Isch-Boschet wird König über Israel", footnotes: ["Isch-Boschet heißt \"Mann der Schande\" und ist offensichtlich eine bewusste Veränderung seines ursprünglichen Namens Eschbaal = \"Mann des Herrn\" (1. Chronik 8,33), aus dem man aber auch den Namen des Gottes Baal heraushören konnte (\"Mann des Baal\").", "Mahanajim lag im Ostjordanland, wahrscheinlich 11 Kilometer östlich vom Jordan am Jabbok."] },
      { number: 9, text: "Dort machte er ihn zum König über Gilead, über die Leute des Stammes Ascher, über Jesreel*, die Stämme Efraïm und Benjamin und so über ganz Israel.", footnotes: ["Jesreel. Es könnte die Stadt Jesreel mitsamt der fruchtbaren Ebene gemeint sein, in der sie lag."] },
      { number: 10, text: "Isch-Boschet Ben-Saul war vierzig Jahre alt, als er König über Israel wurde, und regierte zwei Jahre. Der Stamm Juda jedoch stand hinter David." },
      { number: 11, text: "Sieben Jahre und sechs Monate regierte David in Hebron als König über Juda." },
      { number: 12, text: "Abner Ben-Ner zog mit den Soldaten des Saulssohnes Isch-Boschet von Mahanajim nach Gibeon*.", heading: "Bürgerkrieg in Israel", footnotes: ["Gibeon lag im Stammesgebiet von Benjamin, zu dem Saul und seine Familie gehörten."] },
      { number: 13, text: "Auch Joab Ben-Zeruja* zog mit Davids Truppe aus. Beim Teich von Gibeon trafen sie aufeinander. Die einen blieben diesseits, die anderen jenseits des Teiches.", footnotes: ["Zeruja war die ältere Schwester Davids (1. Chronik 2,16), sodass Joab, Abischai und Asaël (V. 18) Davids Neffen waren."] },
      { number: 14, text: "Da sagte Abner zu Joab: \"Lassen wir unsere jungen Männer doch zu einem Kampfspiel antreten!\" – \"Einverstanden\", sagte Joab." },
      { number: 15, text: "So standen sie auf und traten gegeneinander an: zwölf für Benjamin und Isch-Boschet und zwölf von den Männern Davids." },
      { number: 16, text: "Die Kämpfenden packten sich gegenseitig beim Kopf, und jeder stieß seinem Gegner das Schwert in die Seite, sodass sie alle gleichzeitig umkamen. Den Ort in der Nähe von Gibeon, wo das geschah, nannte man Steinklingenfeld." },
      { number: 17, text: "Nun kam es zwischen den Truppen zum erbitterten Kampf. Die Männer Israels unter Abner wurden von den Männern Davids besiegt." },
      { number: 18, text: "Alle drei Söhne der Zeruja waren an dem Kampf beteiligt: Joab, Abischai und Asaël. Asaël war schnell wie eine wilde Gazelle." },
      { number: 19, text: "Er jagte Abner hinterher und ließ sich durch nichts von ihm ablenken." },
      { number: 20, text: "Als Abner sich umblickte, rief er: \"Bist du das, Asaël?\" Dieser bejahte." },
      { number: 21, text: "Da sagte Abner zu ihm: \"Geh nach rechts oder links und pack dir einen von den jungen Leuten. Dem kannst du die Rüstung abnehmen.\" Aber Asaël wollte nicht von ihm lassen." },
      { number: 22, text: "Da sagte Abner noch einmal zu ihm: \"Lass ab von mir, sonst muss ich dich zu Boden schlagen. Dann kann ich deinem Bruder Joab nicht mehr unter die Augen kommen.\"" },
      { number: 23, text: "Doch Asaël wollte nicht. Da stieß ihm Abner das hintere Ende* seines Speers in den Bauch, sodass der Speer hinten wieder herauskam. Asaël stürzte zu Boden und starb an dieser Stelle. Und jeder, der an die Stelle kam, wo Asaël gefallen war, blieb betroffen stehen.", footnotes: ["Das hintere Ende eines Speers war leicht angespitzt oder es saß ein spitzer Metallschuh darauf, um die Waffe in die Erde stecken zu können (siehe 1. Samuel 26,7)."] },
      { number: 24, text: "Joab und Abischai aber jagten hinter Abner her. Als die Sonne unterging, kamen sie zum Hügel Amma, der östlich von Giach am Weg in die Steppe von Gibeon liegt." },
      { number: 25, text: "Die Männer von Benjamin sammelten sich um Abner und stellten sich dicht geschlossen auf dem Gipfel des frei stehenden Hügels auf." },
      { number: 26, text: "Da rief Abner Joab zu: \"Soll das Schwert denn unaufhörlich weiterfressen? Weißt du nicht, dass am Ende Bitterkeit bleibt? Wann willst du endlich deinen Leuten befehlen, von der Verfolgung ihrer Brüder abzulassen?\"" },
      { number: 27, text: "Joab erwiderte: \"So wahr Gott lebt, hättest du jetzt nichts gesagt, dann hätten meine Leute sich erst am Morgen von der Verfolgung ihrer Brüder zurückgezogen.\"" },
      { number: 28, text: "Darauf blies Joab das Signalhorn. Da gaben seine Männer die Verfolgung auf und stellten den Kampf gegen Israel ein." },
      { number: 29, text: "Abner und seine Leute marschierten die ganze Nacht durch die Jordanebene. Sie überquerten den Fluss und kehrten durch die Schlucht nach Mahanajim zurück." },
      { number: 30, text: "Als Joab die Verfolgung Abners abgebrochen hatte, sammelte er die ganze Truppe um sich. Da wurden von Davids Leuten außer Asaël noch 19 Mann vermisst." },
      { number: 31, text: "Seine Leute aber hatten vom Stamm Benjamin und von den Männern Abners 360 Mann erschlagen." },
      { number: 32, text: "Sie nahmen Asaël mit und bestatteten ihn im Grab seines Vaters in Bethlehem. Joab und seine Männer marschierten noch die ganze Nacht hindurch und kamen bei Tagesanbruch in Hebron an." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Der Krieg zwischen den Anhängern Sauls und dem Königshaus Davids zog sich lange hin. David wurde dabei fortwährend stärker, während das Haus Sauls immer schwächer wurde." },
      { number: 2, text: "In Hebron wurden David folgende Söhne geboren: Sein Ältester war Amnon von seiner Frau Ahinoam aus Jesreel,", heading: "Davids Frauen und Söhne in Hebron" },
      { number: 3, text: "sein zweiter Kilab von Abigajil, der Witwe Nabals aus Karmel, sein dritter Abschalom, den ihm Maacha, die Tochter von König Talmai aus Geschur*, geboren hatte.", footnotes: ["Geschur. Kleines Königreich nördlich von Gilead."] },
      { number: 4, text: "Der vierte war Adonija, Sohn der Haggit, der fünfte Schafatja, Sohn der Abital," },
      { number: 5, text: "und der sechste Jitream von Davids Frau Egla. Diese Söhne wurden David in Hebron geboren." },
      { number: 6, text: "Solange der Krieg zwischen den Königshäusern Saul und David dauerte, stand Abner dem Haus Sauls treu zur Seite.", heading: "David und Abner" },
      { number: 7, text: "Saul hatte eine Nebenfrau gehabt, Rizpa Bat-Aja. Eines Tages stellte Isch-Boschet Abner zur Rede und sagte: \"Warum hast du mit der Nebenfrau meines Vaters geschlafen?\"" },
      { number: 8, text: "Über diese Frage wurde Abner so wütend, dass er Isch-Boschet anfuhr: \"Bin ich vielleicht so ein Hundesohn, der es mit Juda hält? Bis heute kämpfe ich mit aller Kraft für das Haus deines Vaters, für seine Brüder und Freunde, und bewahrte es davor, in die Hand Davids zu fallen, und da wirfst du mir diese Frauengeschichte vor?" },
      { number: 9, text: "Jahwe soll mir alles Mögliche antun, wenn ich jetzt nicht genau das tue, was Jahwe David geschworen hat." },
      { number: 10, text: "Er wird nämlich das Königtum vom Haus Sauls wegnehmen und Davids Thron über Israel und Juda von Dan bis Beerscheba* aufrichten.\"", footnotes: ["Dan bis Beerscheba meint vom nördlichsten bis zum südlichsten Ort in Israel."] },
      { number: 11, text: "Isch-Boschet konnte Abner kein Wort mehr erwidern, solche Angst hatte er vor ihm." },
      { number: 12, text: "Darauf schickte Abner in eigener Sache Boten zu David und ließ ihm sagen: \"Wem steht denn das Land zu? Ich schlage vor: Schließ einen Bund mit mir, und ich werde alles für dich tun, dass ganz Israel zu dir übergeht.\"" },
      { number: 13, text: "David antwortete ihm: \"Gut, ich schließe einen Bund mit dir, aber nur unter einer Bedingung: Du musst Michal, die Tochter Sauls, mitbringen. Sonst brauchst du dich nicht bei mir sehen zu lassen.\"" },
      { number: 14, text: "Gleichzeitig schickte David Boten zu Isch-Boschet Ben-Saul und ließ ihm sagen: \"Gib mir meine Frau Michal heraus, für die ich als Brautpreis hundert Vorhäute der Philister bezahlt habe.\"" },
      { number: 15, text: "Da ließ Isch-Boschet sie von ihrem Mann Paltiel Ben-Lajisch wegholen." },
      { number: 16, text: "Ihr Mann ging mit ihr. Er lief laut weinend hinter ihr her bis nach Bahurim*. Schließlich sagte Abner zu ihm: \"Geh nun, kehr um!\" Da kehrte er zurück.", footnotes: ["Bahurim lag am östlichen Hang des Ölbergs, etwa 2,5 km von Jerusalem entfernt, auf dem Weg zum Jordan"] },
      { number: 17, text: "Zuvor hatte sich Abner mit den Ältesten Israels getroffen und ihnen gesagt: \"Ihr wolltet doch schon lange, dass David euer König wird." },
      { number: 18, text: "Jetzt könnt ihr es haben. Denn Jahwe hat von David gesagt: 'Durch meinen Diener David will ich mein Volk Israel aus der Gewalt der Philister und aller seiner Feinde retten.'\"" },
      { number: 19, text: "Auch zu den Leuten des Stammes Benjamin hatte Abner so gesprochen. Dann ging er nach Hebron, um David alles vorzutragen, was die Israeliten und Benjaminiten für gut hielten." },
      { number: 20, text: "Als Abner nun von zwanzig Männern begleitet nach Hebron kam, gab David ein Festessen für sie." },
      { number: 21, text: "Dann sagte Abner zu David: \"Ich gehe jetzt und werde ganz Israel zu meinem Herrn und König versammeln, damit sie einen Bund mit dir schließen und du König über alles bist, wonach du Verlangen hast.\" David verabschiedete Abner, und er zog in Frieden weg." },
      { number: 22, text: "Inzwischen kamen die Leute Davids mit Joab von einem Streifzug und brachten viel Beute mit. Abner befand sich zu diesem Zeitpunkt nicht mehr bei David in Hebron. David hatte ihn verabschiedet, und er war in Frieden weggezogen.", heading: "Abners Tod" },
      { number: 23, text: "Kaum war Joab mit dem Heer angekommen, berichtete man ihm: \"Abner Ben-Ner ist zum König gekommen, und der hat ihn in Frieden ziehen lassen.\"" },
      { number: 24, text: "Da ging Joab zum König und sagte: \"Was hast du da getan? Abner ist zu dir gekommen, und du hast ihn ungehindert wieder ziehen lassen?" },
      { number: 25, text: "Du kennst doch Abner Ben-Ner! Er ist nur gekommen, um dich zu beschwatzen und zu erfahren, was du vorhast.\"" },
      { number: 26, text: "Joab ging von David weg und schickte Abner Boten nach. Die holten ihn bei der Zisterne von Sira ein und ließen ihn umkehren. David wusste nichts davon." },
      { number: 27, text: "Als Abner wieder nach Hebron kam, führte ihn Joab beiseite in eine der Torkammern, als wollte er ungestört mit ihm reden. Dort stach er ihn in den Bauch, sodass er starb. So rächte er seinen Bruder Asaël." },
      { number: 28, text: "Als David später davon hörte, sagte er: \"Vor Jahwe trifft mich und mein Königtum auf ewig keine Schuld am Blut von Abner Ben-Ner!" },
      { number: 29, text: "Es breche über Joab herein, es falle auf seine Familie! In Joabs Familie soll immer jemand an krankhaften Ausflüssen leiden oder Aussatz haben, an Krücken gehen, gewaltsam umkommen oder hungern müssen!\"" },
      { number: 30, text: "Joab und Abischai hatten Abner umgebracht, weil er ihren Bruder Asaël in der Schlacht bei Gibeon getötet hatte." },
      { number: 31, text: "David befahl Joab und allen seinen Männern: \"Macht Risse in eure Gewänder, legt den Trauersack an und haltet die Totenklage im Trauerzug! Ihr geht vor Abner her!\" Der König selbst ging hinter der Bahre." },
      { number: 32, text: "Sie bestatteten Abner in Hebron. Der König weinte laut an seinem Grab, und das ganze Volk weinte mit." },
      { number: 33, text: "Dann sang der König ein Klagelied für Abner:\"Musste Abner sterben, / wie ein Dummkopf stirbt?" },
      { number: 34, text: "Deine Hände waren nicht gebunden, / deine Füße nicht in Ketten gelegt. / Du bist gefallen, / wie man durch Verbrecher fällt!\"Da weinte das Volk noch mehr über ihn." },
      { number: 35, text: "Dann kamen die Leute, um David Brot zu reichen, weil der Tag noch nicht zu Ende war. Doch David schwor: \"Gott möge mir dies und jenes antun, wenn ich vor Sonnenuntergang auch nur einen Bissen Brot oder sonst etwas esse!\"" },
      { number: 36, text: "Alle Leute nahmen das zur Kenntnis und es gefiel ihnen gut, wie überhaupt alles, was der König tat. Es hatte den Beifall des ganzen Volkes." },
      { number: 37, text: "An diesem Tag erkannten alle, die dabei waren, und ganz Israel, dass der König nichts mit dem Mord an Abner zu tun gehabt hatte." },
      { number: 38, text: "Der König sagte zu seinen Dienern: \"Es ist euch doch klar, dass heute ein Fürst, ein bedeutender Mann in Israel gefallen ist?" },
      { number: 39, text: "Ich bin, obwohl zum König gesalbt, heute noch zu schwach und diesen Söhnen der Zeruja nicht gewachsen. Sie sind härter als ich. Möge Jahwe den, der Böses tut, nach seiner Bosheit bestrafen!\"" },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Als Isch-Boschet Ben-Saul hörte, dass Abner in Hebron umgekommen war, verlor er jeden Mut. Auch ganz Israel war bestürzt.", heading: "Isch-Boschets Tod" },
      { number: 2, text: "Zwei Truppenführer hatte er in seinem Dienst. Der eine hieß Baana, der andere Rechab. Es waren Söhne Rimmons, Benjaminiten aus Beerot, denn auch Beerot* wird zu Benjamin gerechnet.", footnotes: ["Beerot gehörte ursprünglich zu den Städten der Gibeoniten (Josua 9,17)."] },
      { number: 3, text: "Die früheren Bewohner der Stadt waren nach Gittajim* geflohen und leben heute noch als Fremde dort.", footnotes: ["Gittajim. Die geografische Lage ist unbekannt. Jedoch wurde die Stadt später von Benjaminiten bewohnt (Nehemia 11,33)."] },
      { number: 4, text: "Es gab auch noch einen Sohn von Jonatan Ben-Saul, der an beiden Füßen gelähmt war. Er war fünf Jahre alt gewesen, als die Nachricht von Saul und Jonatan aus Jesreel kam. Da hatte ihn seine Amme auf den Arm genommen, um mit ihm zu fliehen. Aber in ihrer Hast ließ sie ihn fallen. Seitdem war er gelähmt. Er hieß Mefi-Boschet*.", footnotes: ["Mefi-Boschet heißt \"aus dem Mund der Schande\" und ist offensichtlich eine bewusste Veränderung seines ursprünglichen Namens Merib-Baal = \"Vom Herrn (oder von Baal) geliebt\" (1. Chronik 8,34). Der Verfasser macht mit diesem Vers deutlich, dass es im Königshaus Sauls nach dem Tod von Isch-Boschet keinen weiteren Anwärter auf den Thron gab."] },
      { number: 5, text: "Rechab und Baana also, die Söhne von Rimmon aus Beerot, gingen zum Haus von Isch-Boschet. In der Nachmittagshitze kamen sie dort an, als Isch-Boschet gerade seinen Mittagsschlaf hielt." },
      { number: 6, text: "Sie taten so, als ob sie Weizen aus der Vorratskammer holen wollten. So gelangten sie ins Innere des Hauses, stachen ihn in den Bauch und konnten wieder entkommen." },
      { number: 7, text: "Sie waren bis in das Schlafzimmer vorgedrungen, in dem Isch-Boschet auf dem Bett lag. Dort hatten sie ihn getötet und ihm den Kopf abgetrennt. Den Kopf nahmen sie mit und marschierten anschließend die ganze Nacht durch die Araba* hindurch.", footnotes: ["Als Araba wird der Jordangraben bezeichnet, der sich von Norden nach Süden durch ganz Israel bis nach Elat am Roten Meer zieht. Er ist zwischen 12,5 und 22,5 km breit und befindet sich fast überall unter der Höhe des Meeresspiegels, am Toten Meer 394 m unter NN."] },
      { number: 8, text: "So kamen sie mit dem Kopf Isch-Boschets nach Hebron zu David. \"Hier ist der Kopf von Isch-Boschet, dem Sohn deines Feindes Saul, der dir nach dem Leben getrachtet hat! So hat Jahwe unserem Herrn und König an diesem Tag Rache an Saul und seinen Nachkommen verschafft.\"" },
      { number: 9, text: "Da erwiderte David Rechab und Baana, den Söhnen von Rimmon aus Beerot: \"So wahr Jahwe lebt, der mich aus jeder Not gerettet hat:" },
      { number: 10, text: "Den Mann, der sich für einen Freudenboten hielt und mir in Ziklag meldete: 'Saul ist tot!', ließ ich umbringen. Das war der Botenlohn für ihn." },
      { number: 11, text: "Wie soll ich dann erst mit Verbrechern verfahren, die einen gerechten Mann auf seinem Bett umgebracht haben? Sollte ich dann nicht sein Blut von euch zurückfordern und euch von der Erde wegschaffen?\"" },
      { number: 12, text: "David befahl seinen Männern, die beiden hinzurichten. Sie taten es, hieben ihnen dann Hände und Füße ab und hingen ihre Leichen am Teich von Hebron auf. Isch-Boschets Kopf aber bestatteten sie im Grab Abners in Hebron." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Alle Stämme Israels kamen zu David nach Hebron und sagten zu ihm: \"Wir sind doch dein Fleisch und Blut.", heading: "Davids Herrschaft über ganz Israel (5-10)\nDavid wird König über ganz Israel" },
      { number: 2, text: "Schon früher, als Saul noch unser König war, hast du Israels Heer in den Kampf geführt und wieder heimgebracht. Und Jahwe hat zu dir gesagt: 'Du sollst der Hirt meines Volkes Israel sein, du sollst Israels Fürst werden!'\"" },
      { number: 3, text: "Das sagten die Ältesten Israels, die zum König nach Hebron gekommen waren. Und König David schloss vor Jahwe einen Bund mit ihnen. Daraufhin salbten sie David zum König über Israel." },
      { number: 4, text: "David war 30 Jahre alt, als er König wurde, und regierte 40 Jahre," },
      { number: 5, text: "siebeneinhalb Jahre über Juda in Hebron und 33 Jahre über ganz Israel und Juda in Jerusalem." },
      { number: 6, text: "Der König zog nun mit seinen Männern nach Jerusalem. Die Jebusiter, die damals noch dort wohnten, sagten zu ihm: \"Du wirst hier nie hereinkommen. Selbst Blinde und Lahme werden dich vertreiben.\" Sie waren sich sicher, dass David die Stadt nicht erobern könnte.", heading: "David erobert Jerusalem" },
      { number: 7, text: "Aber David nahm die Bergfestung Zion ein, und sie wurde zur Davidsstadt." },
      { number: 8, text: "Er sagte damals: \"Wer in den Wasserschacht* gelangt und die Jebusiter überwältigt, soll diese Blinden und Lahmen erschlagen, die mir so verhasst sind!\" Deshalb sagt man: \"Ein Blinder und ein Lahmer, die dürfen nicht ins Haus!'\"", footnotes: ["Wasserschacht. Wahrscheinlich hatte David Kenntnis von einem geheimen Wassertunnel bekommen, durch den die Jebusiter das Wasser aus der Gihon-Quelle in die Stadt leiteten."] },
      { number: 9, text: "David machte die Bergfestung zu seinem Wohnsitz und nannte sie \"Davidsstadt\". Er baute sie ringsum aus, vom Stadtwall an nach innen." },
      { number: 10, text: "So wurde David immer mächtiger, und Jahwe, der allmächtige Gott, stand ihm bei." },
      { number: 11, text: "König Hiram von Tyrus* schickte eine Gesandtschaft zu David. Er lieferte ihm Zedernholz für seinen Palast und schickte Zimmerleute und Steinmetze zum Bauen.", footnotes: ["Tyrus war eine wichtige Hafenstadt in Phönizien (heute: Libanon)."] },
      { number: 12, text: "So erlebte David, wie Jahwe ihn als König über Israel bestätigte und aus Liebe zu seinem Volk Israel sein Königtum zu Ansehen brachte." },
      { number: 13, text: "Nachdem David von Hebron nach Jerusalem gezogen war, nahm er noch weitere Nebenfrauen und Frauen aus Jerusalem und bekam noch mehr Söhne und Töchter." },
      { number: 14, text: "Seine in Jerusalem geborenen Söhne waren Schammua, Schobab, Natan und Salomo," },
      { number: 15, text: "Jibhar, Elischua, Nefeg und Jafia," },
      { number: 16, text: "Elischama, Eljada und Elifelet." },
      { number: 17, text: "Als die Philister hörten, dass David zum König über Israel gesalbt worden war, kamen sie mit ihrem ganzen Heer, um David zu stellen. Sobald David das erfuhr, verschanzte er sich in einer der Bergfestungen.", heading: "Der Krieg mit den Philistern" },
      { number: 18, text: "Die Philister breiteten sich in der Ebene von Refaïm* aus.", footnotes: ["Die Ebene Refaïm ist ein fruchtbares Gebiet westlich von Jerusalem."] },
      { number: 19, text: "Da fragte David Jahwe: \"Soll ich die Philister angreifen? Wirst du sie in meine Hand geben?\" Jahwe erwiderte David: \"Greif sie an! Ich gebe sie in deine Gewalt!\"" },
      { number: 20, text: "Da zog David aus und besiegte die Philister bei Baal-Perazim. Er sagte: \"Wie Wasser einen Damm durchbricht, hat Jahwe die Schlachtreihen meiner Feinde vor mir durchbrochen.\" Deshalb nannte man jenen Ort Baal-Perazim, Herr der Durchbrüche." },
      { number: 21, text: "Die fliehenden Philister ließen sogar ihre Götzenbilder zurück. David und seine Männer nahmen sie als Beute mit." },
      { number: 22, text: "Doch einige Zeit später kamen die Philister wieder und breiteten sich in der Ebene Refaïm aus." },
      { number: 23, text: "David fragte Jahwe, was er tun solle, und dieser antwortete: \"Greif sie diesmal nicht direkt an, sondern umgehe sie und fall ihnen von den Bakabäumen* her in den Rücken.", footnotes: ["Bakabaum. Vielleicht ein anderes Wort für den Maulbeerbaum (Sykomore)."] },
      { number: 24, text: "Sobald du ein Geräusch hörst, so als ob jemand durch die Baumwipfel schreitet, dann beeile dich! Denn dann ist Jahwe vor dir her in die Schlacht gezogen, um das Heerlager der Philister zu schlagen.\"" },
      { number: 25, text: "David machte es so, wie Jahwe es ihm befohlen hatte. Er schlug die Philister von Geba* zurück bis dahin, wo es nach Geser* geht.", footnotes: ["Geba lag 9 km nordöstlich von Jerusalem an der Grenze Judas.", "Geser. Die alte kanaanitische Königsstadt lag 27 km südöstlich von Joppe und gehörte zu dieser Zeit wahrscheinlich den Philistern."] },
    ] },
    { number: 6, verses: [
      { number: 1, text: "David brachte erneut alle zusammen, die in Israel ausgewählt worden waren, 30.000 Mann.", heading: "Die Bundeslade kommt nach Jerusalem" },
      { number: 2, text: "Dann zog er mit allen, die bei ihm waren, nach Baala* in Juda, um von dort die Lade Gottes nach Jerusalem zu holen, die Lade, die dem Namen Jahwes geweiht ist, dem Namen des Allmächtigen, der über den Cherubim* thront.", footnotes: ["Baala in Juda ist ein anderer Name für Kirjat-Jearim, wo sich die Bundeslade während der Zeit Sauls befand (1. Samuel 7,1).", "Cherub, Mehrzahl: Cherubim: Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert."] },
      { number: 3, text: "Sie luden die Lade auf einen neuen unbenutzten Wagen und brachten sie aus dem Haus Aminadabs fort. Aminadabs Haus stand auf einem Hügel. Seine Söhne Usa und Achjo führten den Wagen." },
      { number: 4, text: "Usa ging neben der Lade, während Achjo vor der Lade herging." },
      { number: 5, text: "David und die Männer Israels tanzten vor Jahwe zu Schlaghölzern, Zithern und Harfen, Tamburin, Rasseln und Zimbeln." },
      { number: 6, text: "Als sie zur Tenne Nachon* kamen, drohten die Rinder den Wagen umzuwerfen. Da griff Usa nach der Lade Gottes und hielt sie fest.", footnotes: ["Tenne Nachon. Hebräisch: Dreschplatz des Erschlagens. So wurde der Dreschplatz Kidons offenbar später auch genannt (Siehe Vers 8 und 1. Chronik 13,9.11)"] },
      { number: 7, text: "Sofort flammte Jahwes Zorn gegen Usa auf. Gott schlug ihn wegen seiner Respektlosigkeit, sodass er dort neben der Lade Gottes starb." },
      { number: 8, text: "Aber auch David überwallte es heiß, weil Jahwe Usa so aus dem Leben gerissen hatte. Darum nannte er den Platz Perez-Usa, Usas Riss, und so heißt er bis heute*.", footnotes: ["bis heute.Vom Standpunkt des Verfassers der Samuelbücher aus."] },
      { number: 9, text: "David bekam an diesem Tag Angst vor Jahwe und sagte: \"Wie kann die Lade Jahwes überhaupt zu mir kommen?\"" },
      { number: 10, text: "Er gab den Plan auf, die Lade Jahwes zu sich in die Davidsstadt zu bringen, und führte sie stattdessen in das Haus Obed-Edoms, der aus Gat stammte." },
      { number: 11, text: "Dort blieb die Lade Jahwes drei Monate stehen. Da segnete Jahwe Obed-Edom und sein ganzes Haus." },
      { number: 12, text: "König David wurde das berichtet. Man sagte ihm: \"Weil die Lade Gottes bei Obed-Edom ist, hat Jahwe sein Haus und alles, was er besitzt, gesegnet.\" Da ging David hin und überführte die Lade Gottes mit großer Freude aus dem Haus Obed-Edoms in die Davidsstadt." },
      { number: 13, text: "Als die Träger der Lade Jahwes sechs Schritte gegangen waren, opferte David einen Stier und ein Mastkalb." },
      { number: 14, text: "David tanzte mit ganzer Hingabe vor Jahwe her. Dabei war er mit einem leinenen Efod* bekleidet.", footnotes: ["Das Efod aus Leinen war offenbar ein ärmelloses Gewand und gehörte zur Dienstkleidung eines Priesters, muss aber von dem Efod des Hohenpriesters (2. Mose 39) unterschieden werden, das aus anderem Material hergestellt wurde."] },
      { number: 15, text: "So brachten David und die Israeliten die Lade Jahwes mit Jubelgeschrei und Hörnerschall hinauf." },
      { number: 16, text: "Als die Lade Jahwes in die Stadt getragen wurde, schaute Michal, die Tochter Sauls, aus dem Fenster. Und als sie sah, wie König David vor Jahwe hüpfte und tanzte, verachtete sie ihn innerlich." },
      { number: 17, text: "Man brachte die Lade in das Zelt, das David für sie errichtet hatte, und stellte sie dort an ihren Platz. David brachte Jahwe Brandopfer und ließ Tiere vor Jahwe zum Dankopfer schlachten." },
      { number: 18, text: "Nach dem Opfermahl segnete er das Volk im Namen Jahwes, des Allmächtigen." },
      { number: 19, text: "Dann ließ er an die ganze große Menge der Israeliten, die Männer und Frauen, je einen Brotfladen, eine Portion Dattelkuchen und eine Portion Rosinenkuchen verteilen. So machten sich die Leute auf den Heimweg." },
      { number: 20, text: "Als David heimkam, um seinem Haus den Segensgruß zu bringen, kam ihm Michal, die Tochter Sauls, entgegen und spottete: \"Wie würdevoll hat sich der König von Israel heute benommen, als er sich vor den Frauen seiner Diener schamlos entblößte, wie es sonst nur das niedrigste Gesindel tut!\"" },
      { number: 21, text: "Doch David erwiderte ihr: \"Vor Jahwe, der mich deinem Vater und allen seinen Nachkommen vorgezogen hat, der mich zum Fürsten über sein Volk Israel gemacht hat, ja, vor ihm will ich tanzen!" },
      { number: 22, text: "Und ich will mich noch geringer als diesmal machen und auch vor mir selbst niedrig erscheinen. Aber bei den Frauen, von denen du sprichst, werde ich zu Ehren kommen.\"" },
      { number: 23, text: "Michal, die Tochter Sauls, blieb ihr Leben lang kinderlos." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Als nun der König in seinem Palast wohnte und Jahwe ihm Ruhe vor all seinen Feinden ringsum verschafft hatte,", heading: "Gottes Zusagen an David" },
      { number: 2, text: "sagte er eines Tages zum Propheten Natan: \"Sieh doch, ich wohne hier in einem Palast aus Zedernholz, und die Lade Gottes steht nur in einem Zelt.\"" },
      { number: 3, text: "Natan sagte zum König: \"Geh ruhig ans Werk und tu, was du auf dem Herzen hast, denn Jahwe ist mit dir!\"" },
      { number: 4, text: "Aber in der folgenden Nacht kam das Wort Jahwes zu Natan:" },
      { number: 5, text: "\"Geh zu meinem Diener David und richte ihm aus: 'So spricht Jahwe: Du willst mir ein Haus bauen, in dem ich wohnen soll?" },
      { number: 6, text: "Seit ich die Söhne Israels aus Ägypten herausführte, habe ich noch nie in einem Haus gewohnt, sondern bin bis heute in einer Zeltwohnung umhergezogen." },
      { number: 7, text: "Habe ich während dieser ganzen Zeit jemals von euch verlangt, mir ein Haus aus Zedernholz zu bauen? Von keinem der Führer Israels, denen ich aufgetragen hatte, mein Volk Israel zu weiden, habe ich so etwas verlangt.'" },
      { number: 8, text: "Darum sollst du meinem Diener David ausrichten: 'So spricht Jahwe, der Allmächtige: Ich selbst habe dich von der Schafherde weggeholt und dich zum Herrscher über mein Volk Israel gemacht." },
      { number: 9, text: "Und wohin du auch gegangen bist, bin ich bei dir gewesen und habe alle deine Feinde vor dir beseitigt. Ich habe deinen Namen berühmt gemacht. Du wirst zu den Großen der Erde gezählt." },
      { number: 10, text: "Ich habe meinem Volk Israel eine Heimat gegeben, ein Land, in dem es sicher leben kann und nicht mehr zittern muss. Böse Menschen werden es nicht mehr unterdrücken wie früher" },
      { number: 11, text: "und auch noch zu der Zeit, als ich Richter über mein Volk Israel einsetzte. Ich habe dir Ruhe vor all deinen Feinden verschafft. Und nun kündigt Jahwe dir an, dass er dir ein Haus bauen wird." },
      { number: 12, text: "Wenn deine Zeit abgelaufen ist und du gestorben bist, werde ich dir einen deiner eigenen Nachkommen auf dem Thron folgen lassen und seine Herrschaft festigen." },
      { number: 13, text: "Der wird dann ein Haus für meinen Namen bauen. Und seinem Königtum werde ich ewigen Bestand geben." },
      { number: 14, text: "Ich werde sein Vater sein, und er soll mir Sohn sein.* Wenn er Unrecht begeht, werde ich ihn mit menschlicher Rute und auf menschliche Weise züchtigen.", footnotes: ["Wird im Neuen Testament im Hebräerbrief zitiert: Hebräer 1,5."] },
      { number: 15, text: "Aber meine Gnade entziehe ich ihm nicht, wie ich sie Saul entzog, den ich vor dir beseitigt habe." },
      { number: 16, text: "Dein Königshaus und deine Königsherrschaft sollen für immer vor mir Bestand haben. Dein Thron steht fest auf ewig.'\"" },
      { number: 17, text: "Natan gab David alles genauso weiter, wie es ihm gesagt und offenbart worden war.", heading: "Davids Dankgebet" },
      { number: 18, text: "Da ging David in das Zelt, setzte sich vor Jahwe nieder und sagte: \"Wer bin ich schon, Jahwe, mein Herr, und was bedeutet meine Familie, dass du mich bis hierher gebracht hast?" },
      { number: 19, text: "Und das war dir noch zu wenig, mein Herr, Jahwe! Du hast sogar Zusagen gemacht, die noch meinen fernen Nachkommen gelten – und das für jemand wie mich, Herr, Jahwe?" },
      { number: 20, text: "Was soll David da noch weiter sagen? Du kennst ja deinen Diener, Herr, Jahwe!" },
      { number: 21, text: "Weil du es versprochen hattest und weil es dein Wille war, hast du all das Große getan, um es deinen Diener erkennen zu lassen." },
      { number: 22, text: "Darum bist du groß, Jahwe, mein Gott! Niemand ist dir gleich. Nach allem, was wir gehört haben, gibt es keinen Gott außer dir." },
      { number: 23, text: "Und welches Volk gleicht deinem Volk Israel? Es ist die einzige Nation auf der Erde, die Gott aus der Sklaverei befreit und zu seinem eigenen Volk gemacht hat. So hat er sich einen Namen gemacht und für dieses Volk große und furchterregende Dinge getan. Aus Ägypten hast du es erlöst und hast andere Nationen samt ihren Göttern vor ihm vertrieben." },
      { number: 24, text: "Für alle Zeiten hast du dir Israel zu deinem Volk gemacht, und du selbst, Jahwe, bist sein Gott geworden." },
      { number: 25, text: "Und nun, Jahwe, Gott, lass die Zusage, die du deinem Diener und seinen Nachkommen gemacht hast, für immer gültig sein, und tu, was du versprochen hast!" },
      { number: 26, text: "Dann wird dein Name groß für alle Zeiten sein, und man wird sagen: 'Jahwe, der Allmächtige, ist Gott über Israel!' Und auch das Königshaus deines Dieners David wird vor dir bestehen." },
      { number: 27, text: "Denn du, Jahwe, allmächtiger Gott Israels, du hast dem Ohr deines Dieners offenbart: 'Ich werde dir ein Haus bauen!' Darum hat dein Diener sich ein Herz gefasst, so zu dir zu beten." },
      { number: 28, text: "Und nun, Jahwe, mein Herr, du allein bist wirklich Gott, und deine Worte sind Wahrheit, und du hast deinem Diener all das Gute versprochen." },
      { number: 29, text: "So lass es dir nun gefallen und segne bitte das Königshaus deines Dieners, dass es für immer vor dir bestehe! Denn du, Herr, Jahwe, du hast es gesagt, und mit deinem Segen wird das Haus deines Dieners für immer gesegnet sein!\"" },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Einige Zeit später schlug David die Philister. Er unterwarf sie und nahm ihnen die Zügel der Herrschaft aus der Hand.", heading: "Davids Siege" },
      { number: 2, text: "Er schlug auch die Moabiter*. Die Besiegten mussten sich nebeneinander auf die Erde legen, und er ließ die Messschnur über Leben und Tod entscheiden. Je zwei Schnurlängen Menschen wurden getötet und eine volle Schnurlänge am Leben gelassen. So unterwarf sich David die Moabiter und machte sie tributpflichtig.", footnotes: ["Die Moabiter lebten östlich vom Toten Meer zwischen den Flüssen Arnon und Zered."] },
      { number: 3, text: "David besiegte auch König Hadad-Eser Ben-Rechob von Zoba*, der gerade ausgezogen war, um seine Macht am oberen Euphrat wiederherzustellen.", footnotes: ["Zoba war ein kleines Königreich nördlich von Damaskus."] },
      { number: 4, text: "David nahm 1700 Reiter* und 20.000 Fußsoldaten von ihm gefangen. Alle Streitwagen ließ er unbrauchbar machen, nur 100 behielt er für sich.", footnotes: ["1700 Respanter. Nach 1. Chronik 18,4 waren es 7000 wie die LXX und einige Texte vom Toten Meer bestätigen. Wahrscheinlich wurde beim Abschreiben des Textes von 2. Samuel versehentlich ein Wort weggelassen."] },
      { number: 5, text: "Als die Syrer von Damaskus König Hadad-Eser von Zoba zu Hilfe kamen, besiegte David auch sie und tötete 20.000 Mann." },
      { number: 6, text: "David legte Besatzungen in das damaszenische Syrien. So wurden die Syrer David untertan und mussten ihm regelmäßig Tribut zahlen. Jahwe half David überall, wohin er auch zog." },
      { number: 7, text: "David erbeutete die goldenen Schilde, die Hadad-Esers Offiziere getragen hatten, und brachte sie nach Jerusalem." },
      { number: 8, text: "Aus den Städten Betach und Berotai, die zu Hadad-Esers Gebiet gehörten, nahm er eine große Menge Bronze mit." },
      { number: 9, text: "Als König Toï von Hamat hörte, dass David die ganze Streitmacht Hadad-Esers vernichtet hatte," },
      { number: 10, text: "schickte er seinen Sohn Joram zu ihm. Er sollte König David Grüße ausrichten und ihn zu seinem Sieg über Hadad-Eser beglückwünschen. Hadad-Eser hatte nämlich ständig gegen Toï Krieg geführt. Joram brachte Geräte aus Gold, Silber und Bronze mit." },
      { number: 11, text: "Auch diese weihte König David Jahwe, ebenso wie das Silber und Gold, das er von den Völkern bekam, die er unterworfen hatte," },
      { number: 12, text: "von den Syrern, den Moabitern und Ammonitern*, von den Philistern, den Amalekitern, und das, was er König Hadad-Eser Ben-Rechob von Zoba abgenommen hatte.", footnotes: ["Die Ammoniter waren nordöstliche Nachbarn der Moabiter."] },
      { number: 13, text: "Einen Namen aber machte sich David, als er die Edomiter im Salztal schlug. 18.000 Mann waren es da." },
      { number: 14, text: "Im ganzen Land Edom setzte er Statthalter ein und machte die Bewohner zu seinen Untertanen. So half Jahwe David überall, wohin er auch zog." },
      { number: 15, text: "David regierte als König über ganz Israel und sorgte für Recht und Gerechtigkeit in seinem Volk." },
      { number: 16, text: "Joab Ben-Zeruja war Oberbefehlshaber über das Heer. Joschafat Ben-Ahilud war Kanzler.", heading: "Davids Beamte" },
      { number: 17, text: "Zadok Ben-Ahitub und Ahimelech Ben-Abjatar waren Priester, Seraja war Staatsschreiber." },
      { number: 18, text: "Benaja Ben-Jojada befehligte die Leibgarde*. Alle Söhne Davids hatten den Rang von Priestern.", footnotes: ["Leibgarde. Wörtlich: Die Kreter und Pleter. Vielleicht sind damit Männer von zwei aus Kreta stammenden Philisterstämmen gemeint, die David als Leibwächter in der königlichen Leibgarde dienten."] },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Eines Tages fragte David: \"Ist eigentlich von Sauls Familie noch jemand am Leben? Um Jonatans willen möchte ich ihm Gutes tun.\"", heading: "David und Mefi-Boschet" },
      { number: 2, text: "Saul hatte einen Gefolgsmann namens Ziba gehabt, der nun zu David gerufen wurde. Der König fragte ihn: \"Bist du Ziba?\" – \"Ja, ich bin dein Diener\", antwortete er." },
      { number: 3, text: "Der König fragte ihn: \"Ist denn keiner von Sauls Familie mehr am Leben? Ich möchte ihm die Güte Gottes erweisen.\" Ziba erwiderte: \"Es gibt noch einen Sohn Jonatans, der an beiden Füßen gelähmt ist.\"" },
      { number: 4, text: "\"Wo ist er?\", fragte der König. \"Er lebt im Haus von Machir Ben-Ammiël in Lo-Dabar* \", erwiderte Ziba.", footnotes: ["Lo-Dabar, Stadt im Ostjordanland, 16 km südöstlich vom See Gennesaret."] },
      { number: 5, text: "Da schickte der König Leute hin und ließ ihn holen." },
      { number: 6, text: "So kam Mefi-Boschet Ben-Jonatan, der Enkel Sauls, zu David und fiel vor ihm auf die Knie mit dem Gesicht auf dem Boden. \"Mefi-Boschet!\", sagte David. \"Ja, ich bin dein Diener\", erwiderte dieser." },
      { number: 7, text: "\"Hab keine Angst!\", sagte David zu ihm. \"Um deines Vaters Jonatan willen möchte ich dir Gutes tun. Ich werde dir alle Ländereien deines Großvaters Saul zurückgeben. Und du darfst immer an meinem Tisch essen.\"" },
      { number: 8, text: "Da warf er sich erneut nieder und sagte: \"Was ist dein Diener schon, dass du dich mir so zuwendest? Ich bin doch nur ein toter Hund!\"" },
      { number: 9, text: "Dann ließ der König Ziba, den Gefolgsmann Sauls, zu sich kommen und sagte zu ihm: \"Alles, was Saul und seiner Familie gehört hat, habe ich dem Enkel deines Herrn zurückgegeben." },
      { number: 10, text: "Du wirst mit deinen Söhnen und Knechten das Land bearbeiten und die Ernte einbringen, damit der Enkel deines Herrn seinen Lebensunterhalt hat. Mefi-Boschet selbst wird immer an meinem Tisch essen.\" Ziba hatte fünfzehn Söhne und zwanzig Knechte." },
      { number: 11, text: "Da sagte Ziba zum König: \"Dein Diener wird alles tun, was mein Herr, der König, ihm befiehlt.\"Mefi-Boschet wurde also an der Königstafel versorgt wie einer der Königssöhne." },
      { number: 12, text: "Er hatte auch noch einen kleinen Sohn namens Micha. Und alle, die zum Haushalt Zibas gehörten, wurden zu Dienern Mefi-Boschets." },
      { number: 13, text: "Er wohnte in Jerusalem, denn er aß ständig an der Tafel des Königs, und er war an beiden Füßen gelähmt." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Einige Zeit später starb der König der Ammoniter und sein Sohn Hanun wurde König.", heading: "Krieg gegen die Ammoniter" },
      { number: 2, text: "David dachte: \"Ich will Hanun Ben-Nahasch Freundlichkeit erweisen, wie sein Vater auch mir gegenüber Freundlichkeit gezeigt hat.\" So schickte er eine Gesandtschaft zu Hanun, um ihm sein Beileid auszusprechen. Als die Gesandten Davids im Ammoniterland ankamen," },
      { number: 3, text: "sagten die Oberen der Ammoniter zu ihrem Herrn: \"Denkst du wirklich, dass David deinen Vater ehren will, wenn er dir sein Beileid ausspricht? Er hat seine Gesandten doch nur geschickt, um die Stadt zu erkunden. Er will sie ausspionieren, um sie später zerstören zu können.\"" },
      { number: 4, text: "Da ließ Hanun die Gesandten Davids ergreifen, ihnen die Hälfte des Bartes abscheren und die Gewänder unten bis zum Gesäß abschneiden, und schickte sie so zurück." },
      { number: 5, text: "Als David erfuhr, wie schwer seine Männer beschämt worden waren, schickte er ihnen Boten entgegen und ließ ihnen sagen: \"Bleibt in Jericho, bis euer Bart wieder gewachsen ist, und kommt dann zurück.\"" },
      { number: 6, text: "Als die Ammoniter merkten, dass sie sich bei David verhasst gemacht hatten, warben sie Soldaten an: 20.000 Mann bei den Syrern von Bet-Rechob* und Zoba, 12.000 Mann von Tob* und den König von Maacha* mit 1000 Mann.", footnotes: ["Bet-Rechob liegt zwischen dem Berg Hermon und dem Libanon-Gebirge.", "Tob. Die Stadt lag nördlich vom Königreich Ammon und östlich vom Stammesgebiet Manasse.", "Maacha war ein kleines syrisches Königreich nördlich und östlich vom See Gennesaret."] },
      { number: 7, text: "Als David davon hörte, ließ er Joab mit dem ganzen Heer und der Elitetruppe ausrücken." },
      { number: 8, text: "Die Ammoniter bezogen Stellung vor dem Tor ihrer Stadt. Aber die Syrer von Zoba und Rechob und die Männer von Tob und Maacha stellten sich in einiger Entfernung auf offenem Feld zur Schlacht auf." },
      { number: 9, text: "Als Joab sah, dass er eine Front vor sich und eine im Rücken hatte, wählte er seine besten Leute aus und stellte sich mit ihnen den Syrern entgegen." },
      { number: 10, text: "Die übrigen sollten sich unter dem Kommando seines Bruders Abischai den Ammonitern entgegenstellen." },
      { number: 11, text: "Joab sagte: \"Wenn die Syrer stärker sind als ich, kommst du mir zu Hilfe. Und wenn dir die Ammoniter zu stark werden, helfe ich dir." },
      { number: 12, text: "Hab Mut und lass uns stark sein für unser Volk und die Städte unseres Gottes! Dann soll Jahwe tun, was ihm gefällt.\"" },
      { number: 13, text: "Joab rückte mit seiner Truppe zur Schlacht gegen die Syrer vor. Da flohen sie vor ihm." },
      { number: 14, text: "Als die Ammoniter sahen, dass die Syrer flohen, ergriffen auch sie vor Abischai die Flucht und zogen sich in die Stadt zurück. Da stellte Joab den Kampf gegen die Ammoniter ein und kehrte nach Jerusalem zurück." },
      { number: 15, text: "Die Syrer jedoch sammelten sich wieder, nachdem sie von Israel geschlagen worden waren.", heading: "Krieg gegen die Syrer" },
      { number: 16, text: "Hadad-Eser ließ auch die syrischen Truppen von jenseits des Euphrat anrücken. Unter dem Befehl seines Heerführers Schobach rückten sie bis Helam* vor.", footnotes: ["Helam lag 56 km östlich vom See Gennesaret an der Nordgrenze des israelischen Ostjordanlandes."] },
      { number: 17, text: "Als David das gemeldet wurde, rief er alle wehrfähigen Männer Israels zusammen, überquerte mit ihnen den Jordan und kam nach Helam. Dort stellten sich ihm die Syrer entgegen, und es kam zur Schlacht." },
      { number: 18, text: "Die Syrer wurden von Israel in die Flucht geschlagen. Davids Männer erschlugen 700 syrische Wagenkämpfer* und 40.000 Mann vom Fußvolk. Auch Schobach, ihren Heerführer, verwundeten sie, dass er dort starb.", footnotes: ["Siehe Anmerkung zu 1. Chronik 19,18."] },
      { number: 19, text: "Als nun all die Könige, die unter der Oberherrschaft Hadad-Esers gestanden hatten, sahen, dass sie geschlagen waren, schlossen sie Frieden mit Israel und unterwarfen sich. Die Syrer wagten es nicht, den Ammonitern noch einmal zu helfen." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Als der Frühling kam, begann wieder die Zeit, in der die Könige ihre Feldzüge unternahmen. Auch David schickte Joab mit seinen Leuten und dem ganzen Heer Israels los. Sie verwüsteten das Land der Ammoniter und belagerten Rabba*. David selbst blieb in Jerusalem.", heading: "11-20: Davids Krisen\nEhebruch und Mord (11-12)\nDavid bricht die Ehe", footnotes: ["Rabba war die Hauptstadt der Ammoniter und lag 38 km östlich vom Jordan, heute: Amman."] },
      { number: 2, text: "Eines Tages, es war schon gegen Abend, erhob sich David von seiner Mittagsruhe und ging auf der Dachterrasse seines Palastes auf und ab. Da fiel sein Blick auf eine Frau, die sich gerade mit Wasser übergoss. Sie war sehr schön." },
      { number: 3, text: "David schickte jemand hin und erkundigte sich nach der Frau. Man sagte ihm: \"Das ist doch Batseba Bat-Eliam, die Frau des Hetiters Urija.\"" },
      { number: 4, text: "David schickte Boten und ließ sie holen. Sie kam zu ihm, und er schlief mit ihr. Sie hatte gerade die vorgeschriebene Reinigung nach ihrer Monatsblutung vorgenommen. Danach ging sie in ihr Haus zurück." },
      { number: 5, text: "Aber die Frau wurde schwanger. Sie schickte jemand zu David und ließ ihm ausrichten: \"Ich bin schwanger.\"" },
      { number: 6, text: "Da schickte David eine Botschaft zu Joab: \"Lass den Hetiter Urija zu mir kommen!\" Joab tat es." },
      { number: 7, text: "Als Urija zu David kam, erkundigte sich der König nach dem Ergehen Joabs und des Heeres und nach dem Stand des Krieges." },
      { number: 8, text: "Dann sagte er zu ihm: \"Geh nach Hause und lass dir die Füße baden!\" Als Urija den Palast verließ, wurde ein Geschenk des Königs hinter ihm hergetragen." },
      { number: 9, text: "Doch Urija ging nicht nach Hause, sondern übernachtete bei den Dienern seines Herrn am Palasteingang." },
      { number: 10, text: "Als David gemeldet wurde, dass Urija nicht nach Hause gegangen war, fragte er ihn: \"Warum bist du nicht nach Hause gegangen? Du hast doch einen langen Weg hinter dir.\"" },
      { number: 11, text: "Urija erwiderte David: \"Die Lade* und die Männer von Israel und Juda wohnen in Zelten, selbst Joab, mein Herr, und seine Offiziere übernachten auf offenem Feld, und da sollte ich in mein Haus gehen, essen und trinken und mit meiner Frau schlafen? So wahr du lebst – bei deinem Leben, das werde ich nicht tun.\"", footnotes: ["Lade. Offenbar wurde die Bundeslade mit in das Feldlager genommen wie schon in 1. Samuel 4,4-8."] },
      { number: 12, text: "Da sagte David zu Urija: \"So bleib auch heute noch hier, morgen lass ich dich gehen!\" Also blieb Urija an diesem und am folgenden Tag in Jerusalem." },
      { number: 13, text: "David lud ihn ein, bei ihm zu essen und zu trinken, und er machte ihn betrunken. Aber am Abend ging Urija wieder nicht nach Hause, sondern legte sich auf sein Lager bei den Dienern seines Herrn." },
      { number: 14, text: "Am nächsten Morgen schrieb David einen Brief an Joab und ließ ihn durch Urija überbringen.", heading: "David lässt den Ehemann ermorden" },
      { number: 15, text: "Darin stand: \"Stellt Urija an die vorderste Front, wo der Kampf am härtesten ist, und zieht euch dann hinter ihm zurück, dass er getroffen wird und stirbt!\"" },
      { number: 16, text: "Joab hatte die Stadt ständig im Blick und wusste, wo ihre besten Kämpfer standen. Dort setzte er Urija ein." },
      { number: 17, text: "Als die Belagerten einen Ausfall machten und Joab ein Gefecht lieferten, fielen einige von Davids Leuten. Auch Urija, der Hetiter, fand dabei den Tod." },
      { number: 18, text: "Joab ließ David über den Verlauf des Kampfes genau unterrichten." },
      { number: 19, text: "Er sagte zu dem Boten: \"Wenn du dem König alle Einzelheiten über den Kampf berichtet hast," },
      { number: 20, text: "wird er vielleicht wütend werden und dich fragen: 'Warum seid ihr beim Kampf so nahe an die Stadt gerückt? Habt ihr nicht gewusst, dass sie von der Mauer herab schießen?" },
      { number: 21, text: "Wer hat denn Abimelech Ben-Jerubbeschet* erschlagen? War es nicht eine Frau, die den Mahlstein einer Handmühle von der Mauer herab auf ihn warf? So kam er vor Tebez um.* Aus welchem Grund seid ihr so nah an die Mauer herangerückt?' Dann sollst du sagen: 'Auch dein Diener Urija, der Hetiter, ist tot.'\"", footnotes: ["Jerubbeschet. Gemeint ist Jerubbaal, also Gideon (Richter 7,1). \"Baal\" soll wie in 2. Samuel 2,8 vermieden werden.", "kam er ... um. Richter 9,50-53."] },
      { number: 22, text: "Der Bote ging zu David und berichtete ihm alles, was Joab ihm aufgetragen hatte." },
      { number: 23, text: "Er sagte: \"Weil die Männer uns überlegen waren, machten sie einen Ausfall und griffen uns auf freiem Feld an. Doch wir drängten sie bis dicht ans Stadttor zurück." },
      { number: 24, text: "Da wurden wir von den Schützen auf der Mauer beschossen, und einige von deinen Leuten starben. Auch dein Diener Urija, der Hetiter, ist tot.\"" },
      { number: 25, text: "Da sagte David dem Boten: \"Richte Joab aus: 'Nimm die Sache nicht so schwer, denn das Schwert frisst mal so und mal so! Verstärke deinen Kampf gegen die Stadt und zerstöre sie!' So sollst du ihm Mut machen.\"" },
      { number: 26, text: "Als Urijas Frau hörte, dass ihr Mann tot war, hielt sie die Totenklage für ihn." },
      { number: 27, text: "Nach Ablauf der Trauerzeit holte David sie zu sich in seinen Palast. Sie wurde seine Frau und gebar ihm einen Sohn. Doch Jahwe missfiel sehr, was David getan hatte." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Jahwe schickte Natan zu David. Der ging zu ihm und sagte: \"Zwei Männer lebten in einer Stadt. Der eine war reich, der andere arm.", heading: "Natans Seelsorge" },
      { number: 2, text: "Der Reiche hatte sehr viele Schafe und Rinder." },
      { number: 3, text: "Der Arme hatte nur ein einziges kleines Lämmchen. Er hatte es gekauft und zog es auf. Es wurde zusammen mit seinen Kindern bei ihm groß. Es aß von seinem Bissen, trank aus seinem Becher und schlief in seinem Schoß. Es war für ihn wie eine Tochter." },
      { number: 4, text: "Da kam ein Besucher zu dem reichen Mann. Doch der brachte es nicht übers Herz, eins von seinen Schafen oder Rindern zu nehmen, um es für den Wanderer zuzurichten. Darum nahm er dem Armen das Lamm weg und setzte es seinem Gast vor.\"" },
      { number: 5, text: "David wurde sehr zornig über diesen Mann und sagte zu Natan: \"So wahr Jahwe lebt: Der Mann, der das getan hat, ist ein Kind des Todes!" },
      { number: 6, text: "Dazu muss er das Lamm vierfach ersetzen. Das ist die Strafe dafür, dass er diese Untat beging und kein Mitleid hatte.\"" },
      { number: 7, text: "Da sagte Natan zu David: \"Du bist der Mann! So spricht Jahwe, der Gott Israels: 'Ich habe dich zum König über Israel gesalbt, ich habe dich aus der Hand Sauls gerettet," },
      { number: 8, text: "ich habe dir den ganzen Besitz deines Herrn gegeben und die Frauen deines Herrn in deinen Schoß gelegt. Ich habe dich zum König über Israel und Juda gemacht. Und wenn das noch zu wenig war, hätte ich dir noch dies und das dazu gegeben." },
      { number: 9, text: "Warum hast du das Wort Jahwes verachtet und getan, was ihm missfällt? Du hast Urija, den Hetiter, mit dem Schwert erschlagen, und dann hast du dir seine Frau genommen! Ihn selbst hast du ja durch das Schwert der Ammoniter umgebracht." },
      { number: 10, text: "Darum wird das Schwert auch von deiner Familie niemals weichen. Denn du hast mich verachtet und die Frau des Hetiters Urija zu deiner Frau gemacht.'" },
      { number: 11, text: "So spricht Jahwe: 'Aus deiner eigenen Familie lasse ich Unglück über dich kommen. Unter deinen Augen werde ich deine Frauen wegnehmen und sie deinem Nächsten geben, dass er am helllichten Tag mit ihnen schlafen wird." },
      { number: 12, text: "Denn du, du hast es im Verborgenen getan, aber ich werde es in aller Öffentlichkeit vor ganz Israel tun.'\"" },
      { number: 13, text: "Da sagte David zu Natan: \"Ich habe gegen Jahwe gesündigt.\" Und Natan sagte zu ihm: \"So hat auch Jahwe deine Sünde weggenommen, dass du nicht sterben musst." },
      { number: 14, text: "Weil du aber den Feinden Jahwes durch diese Sache Anlass zur Lästerung gegeben hast, muss der Sohn, der dir geboren wird, sterben.\"" },
      { number: 15, text: "Dann ging Natan nach Hause. Jahwe ließ das Kind, das Urijas Frau David geboren hatte, schwer krank werden.", heading: "Davids Kampf um das Kind" },
      { number: 16, text: "David suchte Gott um des Jungen willen und hielt ein strenges Fasten. Wenn er zum Schlafen heimkam, legte er sich auf den nackten Boden." },
      { number: 17, text: "Die Ältesten seines Hofes versuchten ihn zum Aufstehen zu bewegen. Aber er ließ es nicht zu und aß auch nicht mit ihnen." },
      { number: 18, text: "Am siebten Tag starb das Kind. Davids Diener wagten es nicht, ihm zu sagen, dass das Kind tot war. \"Schon als das Kind noch lebte\", sagten sie zueinander, \"hat er nicht auf uns gehört. Wie können wir ihm jetzt sagen, dass das Kind tot ist? Es würde Unheil anrichten.\"" },
      { number: 19, text: "Als David merkte, dass seine Diener miteinander flüsterten, wurde ihm klar, dass das Kind tot war. Er fragte sie: \"Ist es tot?\" – \"Ja\", erwiderten sie." },
      { number: 20, text: "Da stand David vom Boden auf, wusch und salbte sich und zog frische Kleidung an. Dann ging er ins Haus Jahwes und warf sich nieder. Wieder in sein Haus zurückgekehrt, ließ er sich etwas zu essen bringen." },
      { number: 21, text: "Da fragten seine Diener ihn: \"Was machst du da für eine Sache? Als das Kind noch lebte, hast du gefastet und geweint. Doch nun, wo es gestorben ist, stehst du auf und isst!\"" },
      { number: 22, text: "Da sagte er: \"Als das Kind noch lebte, habe ich gefastet und geweint, weil ich dachte: 'Wer weiß, vielleicht wird Jahwe mir gnädig sein und lässt es am Leben.'" },
      { number: 23, text: "Aber jetzt ist es tot. Wozu soll ich dann noch fasten? Kann ich es damit etwa zurückbringen? Ich werde ihm einmal nachfolgen – aber zu mir kommt es nicht wieder zurück.\"" },
      { number: 24, text: "David tröstete seine Frau Batseba. Er schlief mit ihr, und sie bekam wieder einen Sohn, den er Salomo nannte. Jahwe liebte ihn.", heading: "Die Geburt Salomos" },
      { number: 25, text: "Deshalb schickte er den Propheten Natan zu David und ließ dem Jungen den Namen Jedidja geben, Liebling Jahwes." },
      { number: 26, text: "Joab kämpfte weiter gegen Rabba, die Königsstadt der Ammoniter, und hatte bereits einen Teil davon erobert.", heading: "Die Eroberung von Rabba" },
      { number: 27, text: "Dann schickte er Boten zu David und ließ ihm sagen: \"Ich habe Rabba bekämpft und die Wasserstadt* bereits erobert.", footnotes: ["Wasserstadt. Der untere Teil der Stadt, der am Bach, dem heutigen Sel Amman, lag."] },
      { number: 28, text: "Komm du nun mit dem Rest der Wehrfähigen und vollende die Belagerung der Stadt, damit nicht ich die Stadt erobere und mein Name über ihr ausgerufen wird!\"" },
      { number: 29, text: "Da zog David mit allen übrigen Männern nach Rabba, griff die Stadt an und eroberte sie." },
      { number: 30, text: "Er nahm ihrem König die Krone vom Kopf und setzte sie selbst auf. Ihr Gewicht betrug 34 Kilogramm*. Sie bestand ganz aus Gold und war mit einem kostbaren Edelstein besetzt. Außerdem nahm er reiche Beute aus der Stadt mit.", footnotes: ["34 Kilogramm. Wörtlich: ein Talent. Die Krone wurde offenbar nur kurz bei besonderen Anlässen getragen."] },
      { number: 31, text: "Die Bevölkerung der Stadt ließ David Zwangsarbeiten verrichten. Er stellte sie an Steinsägen, eiserne Pickel, eiserne Beile und Ziegelformen. So machte er es auch mit den anderen Städten der Ammoniter. Dann kehrte er mit dem ganzen Heer nach Jerusalem zurück." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Davids Sohn Abschalom hatte eine schöne Schwester. Sie hieß Tamar. Eines Tages verliebte sich Amnon, ein anderer Sohn Davids, in sie.", heading: "Familienprobleme (13-14)\nAmnons Schandtat" },
      { number: 2, text: "Amnon begehrte sie so sehr, dass er krank wurde. Sie war noch unberührt, und er sah keine Möglichkeit, an sie heranzukommen." },
      { number: 3, text: "Nun hatte er einen Freund namens Jonadab. Das war der Sohn von Davids Bruder Schima. Er war ein sehr kluger Mann." },
      { number: 4, text: "Er sagte zu Amnon: \"Was ist los mit dir, Prinz? Warum bist du Morgen für Morgen so elend? Willst du es mir nicht sagen?\" – \"Ich habe mich in Tamar, die Schwester meines Bruders Abschalom, verliebt\", erwiderte er." },
      { number: 5, text: "Da riet Jonadab ihm: \"Leg dich auf dein Bett und stell dich krank. Wenn dann dein Vater nach dir sieht, sag zu ihm: 'Könnte nicht meine Schwester* Tamar zu mir kommen und mir die Krankenkost bringen? Wenn sie sie hier vor meinen Augen zubereitet, dass ich zusehen kann, werde ich essen, was sie mir gibt.'\"", footnotes: ["meine Schwester. Tamar war die Halbschwester Amnons, weil sie eine andere Mutter als er hatte."] },
      { number: 6, text: "Amnon legte sich also hin und stellte sich krank. Als der König ihn besuchte, sagte Amnon zu ihm: \"Könnte nicht meine Schwester Tamar kommen und vor meinen Augen zwei Herzkuchen formen? Was sie mir gibt, werde ich essen.\"" },
      { number: 7, text: "Da schickte David jemand zu Tamar ins Haus und ließ ihr sagen: \"Geh doch ins Haus deines Bruders Amnon und mach ihm etwas zu essen!\"" },
      { number: 8, text: "So ging Tamar ins Haus Amnons, während er sich hingelegt hatte. Sie nahm Teig, knetete ihn, formte vor seinen Augen die Herzkuchen und backte sie." },
      { number: 9, text: "Dann nahm sie die Pfanne und richtete es ihm zu. Aber er weigerte sich zu essen. \"Es sollen erst alle hinausgehen!\", verlangte er. Als alle weg waren," },
      { number: 10, text: "sagte er zu Tamar: \"Bring die Krankenkost ins Schlafzimmer. Ich werde nur essen, wenn du es mir direkt gibst.\" Da nahm Tamar die Herzkuchen, die sie gebacken hatte, und brachte sie ihrem Bruder ans Bett." },
      { number: 11, text: "Als sie ihm etwas davon reichte, packte er sie und sagte: \"Komm Schwester, schlaf mit mir!\"" },
      { number: 12, text: "\"Nicht doch, mein Bruder!\", rief sie. \"Zwing mich nicht zu so etwas! Das darf man in Israel nicht tun! Diese Schandtat darfst du nicht begehen!" },
      { number: 13, text: "Und ich, wo sollte ich mit meiner Schande hin? Und du würdest als einer der Niederträchtigsten in Israel dastehen. Sprich doch mit dem König! Er wird mich dir sicher nicht verweigern.\"" },
      { number: 14, text: "Doch Amnon wollte nicht auf sie hören. Er fiel über sie her und vergewaltigte sie." },
      { number: 15, text: "Danach aber wurde Amnon wütend auf sie und fing an, sie regelrecht zu hassen. Sein Hass auf sie war größer als sein Verlangen vorher. \"Steh auf und mach dich fort!\", schrie er sie an." },
      { number: 16, text: "\"Nein, jag mich jetzt nicht weg!\", flehte sie. \"Das Unrecht wäre noch schlimmer als das andere, das du mir angetan hast.\" Aber er wollte nicht auf sie hören," },
      { number: 17, text: "sondern rief den jungen Mann, der in seinen Diensten stand, und sagte: \"Schaff mir die da fort! Los, weg mit ihr! Hinaus! Und schließ die Tür hinter ihr zu!\"" },
      { number: 18, text: "Sie trug ein Kleid mit langen Ärmeln, denn solche Gewänder zogen die Töchter des Königs an, solange sie noch unberührt waren. Als nun der Diener sie hinausbrachte und die Tür hinter ihr zuschloss," },
      { number: 19, text: "streute Tamar Staub auf ihren Kopf, zerriss das langärmlige Kleid, das sie anhatte, legte eine Hand auf den Kopf und lief schreiend davon." },
      { number: 20, text: "Ihr Bruder Abschalom fragte sie: \"War dein Bruder Amnon mit dir zusammen? Nun denn, sprich nicht darüber, meine Schwester. Er ist ja dein Bruder. Nimm dir diese Sache nicht zu Herzen.\" Da blieb Tamar vereinsamt und verstört im Haus ihres Bruders Abschalom wohnen.", heading: "Abschaloms Rache" },
      { number: 21, text: "Als König David erfuhr, was geschehen war, wurde er sehr zornig." },
      { number: 22, text: "Abschalom aber sprach kein Wort mehr mit Amnon, denn er hasste ihn, weil er seine Schwester Tamar vergewaltigt hatte." },
      { number: 23, text: "Zwei Jahre später hatte Abschalom Schafschur in Baal-Hazor in der Nähe von Efraïm*. Dazu hatte er alle Königssöhne eingeladen.", footnotes: ["Efraïm.Gemeint ist wahrscheinlich der Ort Efron, 21 km nördlich von Jerusalem."] },
      { number: 24, text: "Das kam so: Er war zum König gegangen und hatte gesagt: \"Dein Diener hat gerade die Schafscherer bei sich. Darf ich den König und seine Diener einladen, mit mir zu feiern?\"" },
      { number: 25, text: "Aber der König sagte zu ihm: \"Nein, mein Sohn. Wir können doch nicht alle zusammen hingehen. Wir wollen dir nicht zur Last fallen.\" Abschalom drängte ihn, aber der König wollte nicht und entließ ihn mit einem Segenswunsch." },
      { number: 26, text: "Da sagte Abschalom noch: \"Kann nicht wenigstens mein Bruder Amnon mitkommen?\" – \"Wozu denn das?\", sagte der König." },
      { number: 27, text: "Abschalom aber drängte ihn. Da ließ er schließlich Amnon und alle anderen Königssöhne mitgehen." },
      { number: 28, text: "Abschalom befahl seinen Gefolgsleuten: \"Passt auf! Wenn der Wein bei Amnon zu wirken beginnt und ich euch sage, dass ihr ihn erschlagen sollt, dann tötet ihn! Habt keine Angst, denn schließlich gebe ich euch den Befehl dazu! Seid mutig und zeigt, dass ihr tapfere Männer seid!\"" },
      { number: 29, text: "Die Leute Abschaloms gehorchten seinem Befehl und töteten Amnon. Da sprangen alle anderen Königssöhne auf, bestiegen ihre Maultiere und flohen." },
      { number: 30, text: "Sie waren noch unterwegs, als David schon das Gerücht erreichte, Abschalom hätte alle Königssöhne erschlagen, keiner wäre entkommen." },
      { number: 31, text: "Da stand der König auf, riss sein Obergewand ein und warf sich zu Boden. Seine Diener standen mit eingerissenen Gewändern um ihn herum." },
      { number: 32, text: "Aber Jonadab, der Sohn von Davids Bruder Schima, sagte: \"Mein Herr muss nicht denken, dass all die jungen Männer, die Königssöhne, umgebracht worden sind. Amnon allein wird tot sein. Von dem Tag an, als Tamar vergewaltigt wurde, war es Abschalom doch anzusehen, dass er entschlossen war, sich an Amnon zu rächen." },
      { number: 33, text: "Der König nehme sich die Sache nicht so zu Herzen. Er soll nicht glauben, dass alle Königssöhne tot sind. Bestimmt wurde nur Amnon getötet.\"" },
      { number: 34, text: "Abschalom war zu dieser Zeit schon geflohen. Der junge Mann, der Ausschau hielt, sah jetzt auf dem Weg vom Westen eine größere Menschenmenge den Berg herabkommen." },
      { number: 35, text: "Da sagte Jonadab zum König: \"Schau, die Königssöhne kommen! Es war genauso, wie dein Diener es gesagt hat.\"" },
      { number: 36, text: "Kaum hatte er das ausgesprochen, da waren die Königssöhne auch schon da und fingen an, laut zu weinen. Auch der König und seine Leute brachen in Tränen aus." },
      { number: 37, text: "Abschalom war zu Talmai* Ben-Ammihud, dem König von Geschur*, geflohen. David trug die ganze Zeit Leid um seinen Sohn.", footnotes: ["Talmai war der Vater seiner Mutter Maacha (2. Samuel 3,3).", "Geschur war ein kleines syrisches Königreich, östlich und nordöstlich vom See Gennesaret."] },
      { number: 38, text: "Abschalom war also nach Geschur geflohen. Dort blieb er drei Jahre.", heading: "Abschaloms Rückkehr" },
      { number: 39, text: "Dann hörte David auf, gegen Abschalom vorzugehen, denn er hatte sich mit Amnons Tod abgefunden." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Joab Ben-Zeruja merkte, dass der König seinen Sohn Abschalom zu vermissen begann." },
      { number: 2, text: "Da ließ er eine kluge Frau aus Tekoa* holen und sagte zu ihr: \"Du sollst die Rolle einer Trauernden spielen. Zieh Trauerkleider an, salbe dich nicht und benimm dich wie eine Frau, die schon lange um einen Toten trauert.", footnotes: ["Tekoa, der Heimatort des Propheten Amos, lag 16 km südlich von Jerusalem."] },
      { number: 3, text: "Geh dann zum König und erzähle ihm das, was ich dir jetzt sage.\" Joab gab ihr seine Anweisungen." },
      { number: 4, text: "Als die Frau aus Tekoa zum König kam, fiel sie vor ihm nieder, mit dem Gesicht zur Erde, und sagte: \"Hilf, mein König!\"" },
      { number: 5, text: "\"Was fehlt dir?\", fragte der König. Da sagte sie: \"Ach, ich bin Witwe, mein Mann ist gestorben." },
      { number: 6, text: "Deine Dienerin hatte zwei Söhne. Die gerieten eines Tages in Streit auf dem Feld. Und weil niemand in der Nähe war, der dazwischentreten konnte, schlug der eine den anderen tot." },
      { number: 7, text: "Und nun ist die ganze Sippe gegen deine Dienerin aufgestanden. Sie fordern, dass ich ihnen den herausgebe, der seinen Bruder erschlagen hat. Sie wollen ihn töten, weil er seinen Bruder umgebracht hat, und so auch den Erben beseitigen. So werden sie den letzten Funken ersticken, der mir noch geblieben ist. Mein Mann wird dann keinen Nachkommen auf der Erde mehr haben, keinen, der seinen Namen weiterträgt.\"" },
      { number: 8, text: "Da sagte der König zu der Frau: \"Geh nach Hause, ich kümmere mich um die Sache!\"" },
      { number: 9, text: "\"Mein Herr und König\", sagte die Frau, \"aber auf mir und der Familie meines Vaters wird die Schuld liegen bleiben. Der König und sein Thron sind nicht betroffen.\"" },
      { number: 10, text: "Da sagte der König: \"Wer darüber etwas zu dir sagt, den bring zu mir! Er wird dich künftig in Ruhe lassen.\"" },
      { number: 11, text: "Aber sie sagte: \"Mein König, sag es doch bitte vor Jahwe, deinem Gott, damit der Bluträcher nicht noch mehr Verderben anrichtet und sie meinen Sohn nicht beseitigen!\" Da sagte er: \"So wahr Jahwe lebt: Kein Haar soll deinem Sohn gekrümmt werden!\"" },
      { number: 12, text: "Darauf sagte die Frau: \"Lass doch deine Dienerin noch ein Wort zu meinem Herrn, dem König, sagen!\" – \"Sprich!\", sagte er." },
      { number: 13, text: "Da sagte sie: \"Warum hast du dann das Gleiche gegen das Volk Gottes im Sinn? Denn nach dem, was der König eben gesagt hat, steht er selbst wie ein Schuldiger da, weil er seinen verstoßenen Sohn nicht wiederkommen lässt." },
      { number: 14, text: "Ja, wir sterben gewiss und sind wie Wasser, das in der Erde verrinnt und das man nicht wieder aufsammeln kann. Aber Gott will das Leben nicht nehmen und möchte auch nicht, dass der Verstoßene von ihm verstoßen bleibt." },
      { number: 15, text: "So bin ich nun hergekommen, um meinem Herrn, dem König, dieses Wort zu sagen, weil die Leute mir Angst machen. Da sagte sich deine Dienerin: 'Ich will mit dem König reden, vielleicht hört er auf das Wort seiner Dienerin.'" },
      { number: 16, text: "Ja, der König wird mir Gehör schenken, um seine Dienerin aus der Gewalt des Mannes zu retten, der meinen Sohn töten und mich aus meinem Erbbesitz drängen will." },
      { number: 17, text: "Und deine Dienerin sagte sich: 'Das Wort meines Herrn und Königs soll mir Beruhigung verschaffen.' Denn mein Herr, der König, ist wie der Engel Gottes und hört heraus, was gut und was böse ist. Jahwe, dein Gott, sei mit dir!\"" },
      { number: 18, text: "Der König antwortete der Frau: \"Ich will dich noch etwas fragen, aber du darfst mir jetzt nichts verschweigen!\" – \"Mein Herr und König möge fragen\", erwiderte sie." },
      { number: 19, text: "\"Hat hier nicht Joab seine Hand im Spiel?\", fragte er. Da rief die Frau: \"So wahr du lebst, mein Herr und König: Wenn du etwas sagst, ist es unmöglich nach rechts oder links auszuweichen! Ja, dein Diener Joab hat mich hergeschickt, und er war es, der deiner Dienerin genau erklärt hat, was sie sagen sollte." },
      { number: 20, text: "Um der Sache ein anderes Aussehen zu geben, hat dein Diener Joab so gehandelt. Aber mein Herr ist weise wie der Engel Gottes und durchschaut alles, was auf der Erde vor sich geht.\"" },
      { number: 21, text: "Da sagte der König zu Joab: \"Gut, ich entscheide die Sache jetzt: Geh also und lass den Jungen, den Abschalom, zurückkehren!\"" },
      { number: 22, text: "Da warf sich Joab zu Boden mit dem Gesicht zur Erde und dankte dem König: \"Jetzt weiß ich, dass dein Diener deine Gunst gefunden hat, mein Herr und König, denn du hast meine Bitte erfüllt.\"" },
      { number: 23, text: "Joab reiste also nach Geschur und brachte Abschalom nach Jerusalem zurück." },
      { number: 24, text: "Dann aber sagte der König: \"Er darf wieder in seinem Haus wohnen, aber empfangen werde ich ihn nicht.\" So lebte Abschalom wieder in seinem Haus, aber zum König durfte er nicht kommen." },
      { number: 25, text: "In ganz Israel gab es keinen Mann von so rühmenswerter Schönheit wie Abschalom. Vom Scheitel bis zur Sohle war alles vollkommen an ihm.", heading: "Abschalom setzt sich durch" },
      { number: 26, text: "Wenn er sich das Kopfhaar schneiden ließ – das geschah einmal im Jahr – dann wog es zweieinhalb Kilogramm*.", footnotes: ["zweieinhalb Kilogramm. Wörtlich: 200 Schekel nach königlichem Gewicht. Der königliche Schekel wog 13 Gramm."] },
      { number: 27, text: "Drei Söhne hatte Abschalom und eine Tochter namens Tamar. Sie war eine sehr schöne Frau." },
      { number: 28, text: "Nun lebte Abschalom schon zwei volle Jahre in Jerusalem, ohne beim König gewesen zu sein." },
      { number: 29, text: "Da ließ er Joab zu sich rufen, um ihn zum König zu schicken. Doch der wollte nicht kommen. Er ließ ihn noch ein zweites Mal bitten, aber Joab weigerte sich." },
      { number: 30, text: "Da sagte Abschalom zu seinen Dienern: \"Passt auf! Das Feld Joabs liegt gleich neben meinem. Er hat dort Gerste stehen. Los, steckt das Getreide in Brand!\" Abschaloms Diener gingen hin und zündeten das Feldstück an." },
      { number: 31, text: "Darauf kam Joab sofort zu Abschalom ins Haus und sagte: \"Warum haben deine Diener meine Gerste angezündet?\"" },
      { number: 32, text: "\"Weil du nicht gekommen bist, als ich dich zu mir bat\", erwiderte Abschalom. \"Ich wollte dich zum König schicken, um ihm zu sagen: 'Wozu bin ich eigentlich von Geschur zurückgekommen? Es wäre besser für mich, wenn ich dort geblieben wäre.' Jetzt will ich zum König vorgelassen werden. Wenn er mich für schuldig hält, dann soll er mich töten.\"" },
      { number: 33, text: "Da ging Joab zum König und richtete ihm die Botschaft aus. Der König ließ Abschalom rufen. Der kam und warf sich vor ihm auf den Boden mit dem Gesicht zur Erde. Und der König küsste Abschalom." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Einige Zeit später schaffte sich Abschalom Wagen und Pferde an und eine fünfzig Mann starke Leibwache.", heading: "Rebellion im Volk (15-20)\nAbschaloms Aufstand beginnt" },
      { number: 2, text: "Jeden Morgen stand er zeitig auf und stellte sich neben den Torweg. Wer einen Streitfall hatte und damit zum König ging, um Recht zu bekommen, kam hier vorbei. Abschalom sprach jeden von ihnen an und fragte: \"Aus welcher Stadt bist du?\" Wenn der dann erwiderte: \"Dein Diener kommt aus einem der Stämme Israels\"," },
      { number: 3, text: "sagte Abschalom zu ihm: \"Deine Sache ist gut und recht, aber du hast niemand beim König, der dich anhört.\"" },
      { number: 4, text: "Dann fügte er hinzu: \"Wenn man doch mich als Richter im Land einsetzen würde! Zu mir könnte jeder kommen, der einen Streitfall oder eine Rechtssache hat. Ich würde ihm zum Recht verhelfen.\"" },
      { number: 5, text: "Und wenn jemand zu ihm kam, um sich vor ihm niederzuwerfen, zog er ihn an sich und küsste ihn." },
      { number: 6, text: "So machte es Abschalom bei allen Israeliten, die zum König kamen, um ihr Recht zu suchen. Auf diese Weise stahl er dem König das Herz der Männer von Israel." },
      { number: 7, text: "Nach vier* Jahren sagte Abschalom zum König: \"Ich möchte nach Hebron gehen und das Gelübde einlösen, das ich Jahwe gegeben habe.", footnotes: ["vier. So mit einigen Manuskripten der syrischen Übersetzung, der LXX, sowie Josephus. Im hebräischen Text steht vierzig, was man eventuell auf das Alter Abschaloms beziehen könnte."] },
      { number: 8, text: "Denn als dein Diener noch in Geschur in Syrien war, habe ich gelobt: 'Wenn Jahwe mich wirklich nach Jerusalem zurückbringt, dann will ich ihm das abdienen.'\"" },
      { number: 9, text: "\"Geh in Frieden\", sagte der König zu ihm. Darauf ging Abschalom nach Hebron." },
      { number: 10, text: "Von dort aus schickte er Geheimboten in alle Stämme Israels und ließ sagen: \"Sobald ihr das Signalhorn hört, ruft: 'Abschalom ist in Hebron König geworden!'\"" },
      { number: 11, text: "Zweihundert Mann aus Jerusalem begleiteten Abschalom. Sie waren als Festgäste eingeladen worden und gingen arglos mit. Von der ganzen Sache wussten sie nichts." },
      { number: 12, text: "Abschalom ließ auch Ahitofel*, den Berater Davids, aus seinem Wohnort Gilo* kommen. Als er nun die Tiere zum Opferfest schlachten ließ, wurde die Verschwörung sehr stark und das Volk bei Abschalom immer zahlreicher.", footnotes: ["Ahitofel war der Großvater Batsebas (siehe Kapitel 11,3; 23,34).", "Gilo war eine Stadt im südlichen Hügelland von Juda, wahrscheinlich nicht weit von Hebron entfernt. Ihre genaue Lage ist unbekannt."] },
      { number: 13, text: "Als ein Bote zu David kam und meldete: \"Das Herz der Männer Israels gehört Abschalom!\",", heading: "Davids Flucht aus Jerusalem" },
      { number: 14, text: "sagte David zu seinen Gefolgsleuten in Jerusalem: \"Los, wir müssen fliehen! Es gibt keine andere Rettung vor Abschalom. Beeilt euch wegzukommen, bevor er hier ist! Wenn er uns einholt, wird er Unheil über uns bringen und ein Blutbad in der Stadt anrichten.\"" },
      { number: 15, text: "Die Gefolgsleute des Königs erwiderten: \"Unser Herr und König entscheidet, wir folgen.\"" },
      { number: 16, text: "So zog der König mit seiner ganzen Familie und seinem Gefolge aus der Stadt. Nur zehn Nebenfrauen ließ er zurück. Sie sollten sich um den Palast kümmern." },
      { number: 17, text: "Beim letzten Haus machte der König mit seinem Gefolge Halt" },
      { number: 18, text: "und ließ alle seine Leute an sich vorüberziehen: seine Leibgarde und auch die 600 Mann, die ihm aus Gat gefolgt waren." },
      { number: 19, text: "Da sagte der König zu Ittai, ihrem Anführer: \"Warum willst du mit uns ziehen? Kehr um und schließ dich dem neuen König an. Du warst ja als Fremder bei uns und bist sogar aus deinem Heimatort verbannt." },
      { number: 20, text: "Gestern erst bist du gekommen und heute sollte ich dich schon wieder aufscheuchen, dass du mit uns ziehst? Ich muss gehen, wohin ich eben gehe. Aber du, kehr um und nimm auch deine Landsleute mit. Erweise ihnen Güte und Treue!\"" },
      { number: 21, text: "Aber Ittai erwiderte dem König: \"So wahr Jahwe lebt und mein Herr und König lebt: Dort, wo mein Herr und König sein wird, werde auch ich sein, im Leben oder im Tod!\"" },
      { number: 22, text: "Da sagte David zu Ittai: \"Dann komm und zieh weiter!\" So zogen Ittai und seine Männer mit ihrem ganzen Tross am König vorbei." },
      { number: 23, text: "Alle, die zurückblieben, weinten laut, als der König mit der ganzen Truppe den Kidronbach überquerte und den Weg in die Wüste einschlug." },
      { number: 24, text: "Und dann war auch Zadok* da und mit ihm alle Leviten, die die Bundeslade trugen. Sie setzten sie ab, und Abjatar* ließ Opferrauch aufsteigen, bis alle Kämpfer aus der Stadt vorbeigezogen waren.", footnotes: ["Zadok war ein Nachkomme Eleasars, des dritten Sohnes Aarons. Er war schon von Saul eingesetzt, Priester an Davids Hof und verantwortlich für die Bundeslade.", "Abjatar war ein Nachkomme Itamars, des vierten Sohnes Aarons. Er teilte sich mit Zadok das Amt des Hohenpriesters."] },
      { number: 25, text: "Dann sagte der König zu Zadok: \"Bring die Lade Gottes wieder in die Stadt. Wenn Jahwe mir gnädig ist, wird er mich zurückbringen und mich sie und ihre Stätte wiedersehen lassen." },
      { number: 26, text: "Wenn er aber sagt: 'Ich habe kein Gefallen mehr an dir!' – hier bin ich, er soll mit mir machen, was er für gut hält.\"" },
      { number: 27, text: "Der König fügte noch hinzu: \"Ich lasse dich als Beobachter hier. Kehrt in Frieden in die Stadt zurück, du und dein Sohn Ahimaaz und auch Abjatar mit seinem Sohn Jonatan." },
      { number: 28, text: "Ich werde an den Jordanfurten zur Wüste hin warten, bis eine Botschaft von euch kommt, die mir Nachricht gibt.\"" },
      { number: 29, text: "So brachten Zadok und Abjatar die Lade Gottes nach Jerusalem zurück und blieben dort." },
      { number: 30, text: "David aber stieg weinend den Ölberg hinauf. Er ging barfuß und hatte sein Gesicht verhüllt. Auch alle, die bei ihm waren, hatten ihr Gesicht verhüllt und weinten." },
      { number: 31, text: "Währenddessen meldete man David: \"Auch Ahitofel ist unter den Verschwörern bei Abschalom.\" Da sagte David: \"O Jahwe, mach doch den Rat Ahitofels zunichte!\"" },
      { number: 32, text: "Als David oben an der Stelle angekommen war, wo man sich vor Gott niederwirft, kam ihm der Arkiter* Huschai entgegen. Er hatte sein Gewand eingerissen und sich Erde auf den Kopf gestreut.", footnotes: ["Die Arkiter gehörten zu einer Sippe aus den Nachkommen Kanaans, die ein Gebiet südwestlich von Bet-El bewohnten."] },
      { number: 33, text: "David sagte zu ihm: \"Wenn du mit mir ziehst, würdest du mir nur zur Last fallen." },
      { number: 34, text: "Wenn du aber in die Stadt zurückkehrst, kannst du mir den Rat Ahitofels zunichte machen. Sag einfach zu Abschalom: 'Ich will dir dienen, mein König! So, wie ich früher deinem Vater gedient habe, will ich nun auch dir dienen.'" },
      { number: 35, text: "Auch die Priester Zadok und Abjatar sind auf deiner Seite. Alles, was du aus dem Königspalast in Erfahrung bringen kannst, sollst du ihnen mitteilen." },
      { number: 36, text: "Sie werden es mir durch ihre beiden Söhne Ahimaaz Ben-Zadok und Jonatan Ben-Abjatar weitermelden.\"" },
      { number: 37, text: "So kam Davids Freund Huschai in die Stadt, als Abschalom gerade in Jerusalem einzog." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Als David die Höhe überschritten hatte, kam ihm Ziba, der Verwalter Mefi-Boschets, entgegen. Er hatte zwei gesattelte Esel bei sich und darauf 200 Brote, 100 Rosinenkuchen, 100 Bündel Sommerobst und einen Schlauch Wein.", heading: "David und Ziba" },
      { number: 2, text: "\"Was willst du damit?\", fragte der König Ziba. Dieser erwiderte: \"Die Esel sind für die Familie des Königs zum Reiten, das Brot und das Sommerobst für deine Männer zum Essen und der Wein zum Trinken für den, der in der Wüste müde wird.\"" },
      { number: 3, text: "\"Und wo ist der Sohn deines Herrn?\", fragte der König. \"Ach, der ist in Jerusalem geblieben\", sagte Ziba. \"Er denkt, dass die Israeliten ihm heute die Königsherrschaft seines Vaters zurückgeben.\"" },
      { number: 4, text: "Da sagte der König zu Ziba: \"Alles, was Mefi-Boschet gehörte, übergebe ich dir.\" – \"Ich beuge mich nieder\", sagte Ziba. \"Möge ich weiter Gunst vor meinem Herrn und König finden!\"" },
      { number: 5, text: "Als König David nach Bahurim* kam, lief ihm ein Mann unter beständigem Fluchen entgegen. Er gehörte zur Sippe Sauls und hieß Schimi Ben-Gera.", heading: "David und Schimi", footnotes: ["Bahurim. Siehe 2. Samuel 3,16"] },
      { number: 6, text: "Er bewarf David und seine Leute mit Steinen, obwohl David von der Leibgarde und den Soldaten umgeben war." },
      { number: 7, text: "\"Hau ab, hau ab, du Bluthund, du Verbrecher!\", schrie und fluchte er." },
      { number: 8, text: "\"Jahwe hat deine Schuld am Blut der Familie Sauls nun über dich gebracht. Du hast ihm ja das Königtum genommen, und nun hat Jahwe es in die Hand deines Sohnes Abschalom gegeben. Jetzt erlebst du die Strafe, du Bluthund!\"" },
      { number: 9, text: "Da sagte Abischai Ben-Zeruja zum König: \"Wie kommt dieser tote Hund dazu, meinem Herrn und König zu fluchen? Lass mich hinübergehen, dass ich ihm den Kopf abschlage!\"" },
      { number: 10, text: "Aber der König sagte: \"In was für eine Sache wollt ihr mich da hineinziehen, ihr Söhne der Zeruja? Soll er doch fluchen! Wenn Jahwe ihm gesagt hat, dass er David fluchen soll, wer darf ihn da zur Rechenschaft ziehen?\"" },
      { number: 11, text: "Dann sagte David zu Abischai und all seinen Leuten: \"Seht doch, mein leiblicher Sohn trachtet mir nach dem Leben! Was kann man da von diesem Benjaminiten erwarten? Lasst ihn, mag er fluchen, wenn Jahwe es ihm gesagt hat." },
      { number: 12, text: "Vielleicht sieht Jahwe auf mein Elend und erweist mir Gutes für den Fluch an diesem Tag.\"" },
      { number: 13, text: "David und seine Männer gingen weiter, während Schimi am Berghang fluchend neben ihm herging und mit Steinen und Erdklumpen nach ihm warf." },
      { number: 14, text: "Der König und seine Leute kamen erschöpft am Fluss an. Dort erholte er sich wieder." },
      { number: 15, text: "Abschalom war mit seinen Leuten und den Männern von Israel in Jerusalem eingezogen. Auch Ahitofel begleitete ihn.", heading: "Abschalom schläft mit Davids Frauen" },
      { number: 16, text: "Als der Arkiter Huschai, der Freund Davids, zu Abschalom kam, sagte er: \"Es lebe der König! Es lebe der König!\"" },
      { number: 17, text: "Doch Abschalom erwiderte: \"Ist das deine Liebe zu deinem Freund? Warum bist du nicht mit ihm gegangen?\"" },
      { number: 18, text: "\"Nein\", antwortete Huschai, \"ich gehöre zu dem, den Jahwe erwählt hat und den alle Männer Israels zu ihrem König gemacht haben. Bei ihm will ich bleiben." },
      { number: 19, text: "Und außerdem: Wem sollte ich denn sonst dienen, wenn nicht seinem Sohn? Wie ich deinem Vater gedient habe, will ich auch dir dienen.\"" },
      { number: 20, text: "Nun sagte Abschalom zu Ahitofel: \"Gib einen Rat! Was sollen wir jetzt tun?\"" },
      { number: 21, text: "Ahitofel sagte: \"Schlaf mit den Nebenfrauen deines Vaters, die den Palast hüten sollten! Wenn sich in Israel herumspricht, dass du dich auf diese Weise bei deinem Vater verhasst gemacht hast, wird das deine Anhänger stärken.\"" },
      { number: 22, text: "So wurde auf der Dachterrasse des Palastes ein Zelt für Abschalom aufgeschlagen. Vor den Augen von ganz Israel ging Abschalom hinein und schlief mit den Nebenfrauen seines Vaters." },
      { number: 23, text: "Ein Rat Ahitofels war damals so, als hätte man das Wort Gottes befragt. So viel galt sein Rat schon bei David und nun auch bei Abschalom." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Ahitofel sagte zu Abschalom: \"Lass mich 12.000 Mann auswählen und noch in dieser Nacht David verfolgen!", heading: "Huschai und Ahitofel" },
      { number: 2, text: "Ich werde über ihn kommen, solange er noch erschöpft und entmutigt ist, und ihn so aufschrecken, dass alle seine Leute fliehen. Dann muss ich nur den König erschlagen." },
      { number: 3, text: "Auf diese Weise kann ich das ganze Volk zurückbringen. Denn wenn du diesen Mann zu fassen bekommst, gewinnst du alle anderen zurück. Dann wird das ganze Volk Frieden haben.\"" },
      { number: 4, text: "Der Vorschlag erschien Abschalom und allen Ältesten Israels gut." },
      { number: 5, text: "Doch Abschalom sagte: \"Ruft auch den Arkiter Huschai her, damit wir hören, was er zu sagen hat!\"" },
      { number: 6, text: "Als Huschai kam, eröffnete Abschalom ihm, was Ahitofel vorgeschlagen hatte, und fragte: \"Sollen wir es so machen? Wenn nicht, rede du!\"" },
      { number: 7, text: "Da sagte Huschai zu Abschalom: \"Der Rat, den Ahitofel diesmal gegeben hat, ist nicht gut.\"" },
      { number: 8, text: "Und er fuhr fort: \"Du kennst doch deinen Vater und seine Männer. Es sind Helden. Und jetzt sind sie verbittert wie eine Bärin, der man die Jungen geraubt hat. Dein Vater ist ein erfahrener Kämpfer. Er wird seinen Leuten keine Nachtruhe gönnen." },
      { number: 9, text: "Gewiss hat er sich jetzt in irgendeiner Höhle oder sonst einem Hinterhalt versteckt. Und wenn dann gleich am Anfang einige von deinen Leuten fallen, wird es heißen: 'Die Anhänger Abschaloms haben eine Niederlage erlitten!'" },
      { number: 10, text: "Dann würde selbst ein tapferer Mann mit dem Herzen eines Löwen den Mut verlieren. Ganz Israel weiß doch, dass dein Vater ein Held ist und dass erprobte Kämpfer bei ihm sind." },
      { number: 11, text: "Deshalb rate ich: Lass ganz Israel von Dan bis Beerscheba zu dir kommen. Mit diesem Heer, so zahlreich wie der Sand am Meer, musst du selbst in den Kampf ziehen." },
      { number: 12, text: "Wenn wir dann auf ihn stoßen, egal, wo er sich gerade befindet, werden wir über ihn herfallen, so wie der Tau auf den Erdboden fällt. Dann wird von ihm und seinen Leuten keiner übrig bleiben." },
      { number: 13, text: "Und wenn er sich in eine Stadt zurückzieht, dann werden die Israeliten Seile an sie legen und sie ins Tal hinunterschleifen, bis kein Kiesel mehr von ihr zu finden ist.\"" },
      { number: 14, text: "Da riefen Abschalom und alle Männer Israels: \"Der Rat des Arkiters Huschai ist besser als der Rat Ahitofels.\" Doch Jahwe hatte es so kommen lassen, um den guten Rat Ahitofels zunichte zu machen und Unheil über Abschalom zu bringen." },
      { number: 15, text: "Huschai berichtete den Priestern Zadok und Abjatar vom Rat Ahitofels und dem, den er selbst Abschalom und den Ältesten Israels gegeben hatte." },
      { number: 16, text: "\"Schickt schnell eine Botschaft zu David\", sagte er. \"Er soll ja nicht auf dieser Seite der Wüstenfurten bleiben, sondern in jedem Fall hinübergehen, damit der König und seine Leute nicht vernichtet werden.\"" },
      { number: 17, text: "Jonatan und Ahimaaz warteten bei der Rogelquelle*, denn sie durften sich nicht in der Stadt sehen lassen. Eine Magd ging zu ihnen und brachte die Nachricht, die sie dem König übermitteln sollten.", footnotes: ["Die Rogelquelle liegt 1,5 km südlich von Jerusalem im Kidrontal."] },
      { number: 18, text: "Doch ein junger Mann sah sie und berichtete es Abschalom. Da rannten beide fort und kamen bis zum Haus eines Mannes in Bahurim. Er hatte einen Brunnen in seinem Hof, in den sie hineinstiegen." },
      { number: 19, text: "Seine Frau legte eine Decke über die Öffnung und streute Getreidekörner darüber aus, sodass nichts zu erkennen war." },
      { number: 20, text: "Als die Männer Abschaloms zu der Frau kamen, fragten sie: \"Wo sind Ahimaaz und Jonatan?\" – \"Sie sind von hier zum Wasser weitergegangen\", sagte die Frau. Sie durchsuchten alles, fanden aber niemand und kehrten schließlich nach Jerusalem zurück." },
      { number: 21, text: "Sobald sie gegangen waren, stiegen die beiden aus dem Brunnen und brachten die Nachricht zu König David. \"Ihr müsst sofort aufbrechen und den Fluss überqueren\", sagten sie und berichteten vom Rat Ahitofels gegen David und seine Leute." },
      { number: 22, text: "Sofort brach David mit allen seinen Leuten auf und überquerte den Jordan. Bei Tagesanbruch war auch der letzte von ihnen am anderen Ufer angelangt." },
      { number: 23, text: "Als Ahitofel sah, dass sein Rat nicht befolgt wurde, sattelte er seinen Esel und kehrte in seine Heimatstadt zurück. Dort regelte er die letzten Dinge mit seiner Familie. Dann erhängte er sich. Er wurde im Grab seines Vaters beigesetzt." },
      { number: 24, text: "David hatte Mahanajim* erreicht, als Abschalom mit dem ganzen Heer Israels den Jordan überschritt.", footnotes: ["Mahanajim. Siehe Kapitel 2,8!"] },
      { number: 25, text: "Abschalom hatte Amasa an Stelle von Joab über das Heer eingesetzt. Amasa war der Sohn des Ismaëliten Jeter*, der mit Abigal Bat-Nahasch* geschlafen hatte, der Schwester von Joabs Mutter Zeruja.", footnotes: ["Ismaeliters Jeter. So mit 1. Chronik 2,17und der LXX. Hebräisch: Israeliten Jitra.", "Nahasch. In 1. Chronik 2,13-17 gelten Abigal und Zeruja als Töchter Isais. Es scheint so zu sein, dass Nahasch ihr leiblicher Vater war und Isai ihre Mutter nach dem Tod von Nahasch geheiratet hatte."] },
      { number: 26, text: "Das Heer Israels unter Abschalom schlug sein Lager im Gebiet von Gilead auf." },
      { number: 27, text: "Als David nach Mahanajim kam, erwarteten ihn dort Schobi Ben-Nahasch aus dem ammonitischen Rabba sowie Machir Ben-Ammiël aus Lo-Dabar und Barsillai aus Roglim in Gilead.", heading: "Unterstützung für David in Mahanajim" },
      { number: 28, text: "Sie hatten Schlafmatten, Metallgefäße und Tongeschirr mitgebracht, Weizen, Gerste und Mehl, geröstete Körner, Bohnen und Linsen," },
      { number: 29, text: "Honig, Butter, Käse und Schafe. Sie hatten sich gedacht, dass Davids Leute nach dem Marsch durch die Wüste hungrig, durstig und müde sein würden." },
    ] },
    { number: 18, verses: [
      { number: 1, text: "David musterte das Heer, das bei ihm war, und setzte Offiziere über Tausend- und Hundertschaften ein.", heading: "Davids Vorbereitungen zum Kampf" },
      { number: 2, text: "Ein Drittel von ihnen unterstellte er Joab, ein Drittel Abischai Ben-Zeruja, und ein Drittel Ittai aus Gat. \"Ich bin entschlossen, mit euch zu ziehen\", sagte er vor dem ganzen Heer." },
      { number: 3, text: "Aber die Männer sagten: \"Du darfst nicht mit uns ziehen. Denn sollten wir fliehen müssen, werden sie sich um uns keine Mühe machen. Selbst wenn die Hälfte von uns fällt, hat das nichts zu bedeuten, denn du bist so viel wert wie zehntausend von uns. Es wäre besser, wenn du uns von der Stadt aus hilfst.\"" },
      { number: 4, text: "\"Ich will tun, was ihr für richtig haltet\", sagte der König. Dann stellte er sich neben das Tor und ließ seine Truppen in Abteilungen geordnet vorbeiziehen." },
      { number: 5, text: "Alle konnten hören, wie der König Joab, Abischai und Ittai befahl: \"Geht mir schonend mit dem Jungen um, mit Abschalom!\"" },
      { number: 6, text: "So zogen Davids Truppen den Israeliten ins offene Land entgegen. Im Wald von Efraïm* kam es zur Schlacht.", heading: "Abschaloms Tod", footnotes: ["Wald von Efraïm. Dass dieses Gebiet in Gilead so heißt, hängt wahrscheinlich damit zusammen, dass die Efraïmiten es einst beansprucht hatten (Richter 12,1-4)."] },
      { number: 7, text: "Dort erlitten die Männer Israels eine schwere Niederlage. 20.000 Mann von ihnen fielen." },
      { number: 8, text: "Der Kampf hatte sich über die ganze Gegend ausgebreitet. Und der Wald forderte mehr Opfer als der Kampf selbst." },
      { number: 9, text: "Auch Abschalom geriet in die Nähe der Soldaten Davids. Er ritt auf einem Maultier*. Als er damit unter die verschlungenen Zweige einer großen Terebinthe* kam, verfing sich sein Kopf in der Terebinthe, sodass er zwischen Himmel und Erde hing, denn das Maultier unter ihm war weitergelaufen.", footnotes: ["Ein Maultier ist die Kreuzung von Eselhengst und Pferdestute. Als Reit- und Tragtiere sind sie ausdauernd und trittsicher besonders auf trockenem Boden. Seit David benutzte man sie als Reittiere im Königs-Haus.", "Die Terebinthe ist ein belaubter Baum mit breitem Wipfel, der nicht mehr als sieben Meter hoch wird."] },
      { number: 10, text: "Einer von den Männern Davids hatte das gesehen und meldete Joab: \"Ich habe Abschalom an einer Terebinthe hängen sehen.\"" },
      { number: 11, text: "\"Wie, du hast ihn gesehen?\", rief Joab. \"Und warum hast du ihn nicht sofort zu Boden geschlagen? Ich hätte dir zehn Silberstücke und einen Gürtel dafür geschenkt.\"" },
      { number: 12, text: "Aber der Mann erwiderte: \"Auch für tausend Silberstücke hätte ich meine Hand nicht gegen den Sohn des Königs erhoben. Denn vor unseren Ohren hat der König dir, Abischai und Ittai befohlen, vorsichtig mit seinem Jungen, mit Abschalom, umzugehen." },
      { number: 13, text: "Und hätte ich heimtückisch gehandelt und ihm etwas angetan – der König hätte es ja doch erfahren –, dann hättest du dich herausgehalten.\"" },
      { number: 14, text: "Da sagte Joab: \"Ich will nicht so viel Zeit mit dir vergeuden!\" Er nahm drei Speere mit und stieß sie Abschalom ins Herz, der immer noch lebend an der Terebinthe hing." },
      { number: 15, text: "Die zehn Waffenträger Joabs umringten Abschalom und schlugen ihn vollends tot." },
      { number: 16, text: "Dann blies Joab das Signalhorn und hielt seine Truppen von der weiteren Verfolgung Israels ab, denn er wollte das Volk schonen." },
      { number: 17, text: "Die Männer Joabs warfen Abschalom in eine tiefe Grube im Wald und errichteten einen großen Steinhaufen über ihm, während das Heer Israels sich auflöste und jeder nach Hause floh." },
      { number: 18, text: "Abschalom hatte schon zu Lebzeiten einen Gedenkstein für sich errichten lassen. Denn er hatte sich gesagt: \"Ich habe keinen Sohn, in dem mein Name fortleben könnte.\" Deshalb gab er dem Stein seinen Namen. Er steht bis heute im Königstal*, und man nennt ihn den Abschalom-Stein.", footnotes: ["Das Königstal ist in der Nähe von Jerusalem (1. Mose 14,17)."] },
      { number: 19, text: "Ahimaaz Ben-Zadok sagte: \"Ich will zum König laufen und ihm die Freudenbotschaft bringen, dass Jahwe ihm aus der Gewalt seiner Feinde zum Recht verholfen hat!\"", heading: "David erfährt von Abschaloms Tod" },
      { number: 20, text: "Aber Joab sagte zu ihm: \"Heute bist du nicht der richtige Mann für die Botschaft. Ein andermal kannst du der Freudenbote sein, an diesem Tag nicht, denn der Sohn des Königs ist ja tot.\"" },
      { number: 21, text: "Joab wandte sich an den Nubier*, der im Dienst des Königs stand: \"Lauf zum König und melde ihm, was du gesehen hast.\" Der Nubier warf sich vor Joab nieder und lief los.", footnotes: ["Nubier. Der Mann stammte aus Nubien (Hebräisch: Kusch), einem Land am Oberlauf des Nil, südlich von Ägypten."] },
      { number: 22, text: "Aber Ahimaaz Ben-Zadok fing noch einmal an und sagte zu Joab: \"Komme, was will, ich möchte doch hinter dem Nubier her laufen.\" – \"Wozu willst du denn laufen?\", erwiderte Joab. \"Du hast doch keine Freudenbotschaft mehr.\"" },
      { number: 23, text: "\"Komme, was da will, ich laufe!\", rief Ahimaaz. \"Dann lauf!\", sagte Joab zu ihm. Ahimaaz nahm den Weg durch die Jordanebenen und überholte den Nubier." },
      { number: 24, text: "David hielt sich zwischen dem äußeren und inneren Stadttor auf, als der Wächter auf die Mauer stieg, den Beobachtungsstand über dem Tor. Als dieser sich umschaute, sah er einen Mann auf die Stadt zulaufen." },
      { number: 25, text: "Der Wächter rief es aus und meldete es dem König. Dieser sagte: \"Wenn er allein ist, bringt er gute Nachricht.\" Während der Mann näher kam," },
      { number: 26, text: "sah der Wächter noch einen anderen laufen. Er rief ins Tor hinein: \"Da kommt noch ein Mann, der allein läuft!\" Der König sagte: \"Auch das ist ein Bote!\"" },
      { number: 27, text: "Da sagte der Wächter: \"So, wie ich sehe, läuft der erste wie Ahimaaz Ben-Zadok.\" Der König sagte: \"Das ist ein guter Mann. Er kommt gewiss mit einer guten Nachricht!\"" },
      { number: 28, text: "Ahimaaz rief: \"Schalom!\", und warf sich vor dem König nieder, mit dem Gesicht zur Erde. \"Gepriesen sei Jahwe, dein Gott!\", stieß er hervor. \"Er hat alle, die sich gegen dich erhoben haben, ausgeliefert.\"" },
      { number: 29, text: "\"Und was ist mit meinem Jungen, mit Abschalom?\", fragte der König. \"Er ist doch hoffentlich unversehrt!\" Ahimaaz erwiderte: \"Ich sah das große Gedränge, als Joab den Diener des Königs und mich, deinen Diener, fortschickte. Aber ich konnte nicht erkennen, was es war.\"" },
      { number: 30, text: "\"Stell dich hier neben mich\", sagte der König zu ihm." },
      { number: 31, text: "Da kam auch schon der Nubier und rief: \"Mein König und Herr lasse sich die gute Nachricht bringen: Jahwe hat dir heute zum Recht verholfen aus der Gewalt aller, die sich gegen dich erhoben haben.\"" },
      { number: 32, text: "\"Ist mein Junge, ist Abschalom, unversehrt?\", fragte der König den Nubier. Dieser erwiderte: \"Möge es den Feinden meines Herrn und Königs und allen, die sich böswillig gegen dich erhoben haben, so ergehen, wie dem Jungen!\"" },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Da durchfuhr es den König, und er stieg weinend in die Wachstube über dem Tor hinauf. \"Mein Sohn Abschalom! Mein Sohn Abschalom!\", rief er im Gehen. \"Wäre ich doch an deiner Stelle gestorben! Abschalom, mein Sohn, mein Sohn!\"", heading: "Davids Trauer um Abschalom" },
      { number: 2, text: "Man berichtete Joab: \"Schau, der König weint und trauert um Abschalom.\"" },
      { number: 3, text: "So wurde der Sieg an diesem Tag zur Trauer für das Volk, denn es hatte sich herumgesprochen: \"Der König grämt sich um seinen Sohn.\"" },
      { number: 4, text: "Da stahlen sich an diesem Tag die Kämpfer in die Stadt, wie Männer sich davonstehlen, wenn sie sich schämen, weil sie in der Schlacht geflohen sind." },
      { number: 5, text: "Der König hatte sein Gesicht verhüllt und schrie immer wieder: \"Mein Sohn Abschalom! Abschalom, mein Sohn, mein Sohn!\"" },
      { number: 6, text: "Da kam Joab zum König ins Haus und sagte: \"Du hast heute alle deine Diener schwer beleidigt. Dabei haben sie dir, deinen Söhnen und Töchtern, deinen Frauen und Nebenfrauen das Leben gerettet!" },
      { number: 7, text: "Du beschämst sie, wenn du liebst, die dich hassen, und hasst, die dich lieben. Du hast heute deutlich gemacht, dass dir deine Oberen und Diener nichts bedeuten. Ja, ich sehe jetzt: Es wäre dir ganz recht, wenn Abschalom noch am Leben wäre, wir alle aber tot!" },
      { number: 8, text: "Steh jetzt auf, geh hinaus und rede zum Herzen deiner Leute! Denn bei Jahwe schwöre ich dir: Wenn du nicht gleich hinausgehst, dann bleibt heute Nacht nicht ein Mann bei dir! Und das wäre schlimmer für dich als alles, was seit deiner Jugendzeit über dich gekommen ist.\"" },
      { number: 9, text: "Da erhob sich der König und setzte sich ins Tor. Als man den Männern berichtete: \"Seht, der König sitzt im Tor!\", kamen sie alle vor den König.Israeliten waren alle nach Hause geflohen." },
      { number: 10, text: "Und nun stritten sie sich in ihren Stämmen. Sie sagten: \"Der König hat uns aus der Gewalt unserer Feinde befreit, auch vor den Philistern hat er uns gerettet. Und jetzt ist er vor Abschalom aus dem Land geflohen.", heading: "Davids Rückkehr nach Jerusalem" },
      { number: 11, text: "Doch Abschalom, den wir zum König über uns gesalbt hatten, ist tot. Warum zögert ihr jetzt, den König zurückzuholen?\"" },
      { number: 12, text: "Auch König David hatte den Priestern Zadok und Abjatar sagen lassen: \"Richtet den Ältesten von Juda aus: 'Warum wollt ihr die Letzten sein, die daran denken, den König in sein Haus zurückzuholen, wo doch schon von ganz Israel der Wunsch an den König herangetragen wurde?" },
      { number: 13, text: "Ihr seid doch meine Brüder, mein eigenes Fleisch und Blut! Warum wollt ihr die Letzten sein, den König zurückzuholen?'" },
      { number: 14, text: "Und zu Amasa sollt ihr sagen: 'Bist du nicht mein eigenes Fleisch und Blut? Gott möge mir dies und jenes antun, wenn du nicht von jetzt ab und für immer an Joabs Stelle Heerführer sein wirst.'\"" },
      { number: 15, text: "So stimmte er das Herz aller Männer von Juda um. Sie traten geschlossen auf seine Seite und ließen dem König ausrichten: \"Komm bitte mit all deinen Leuten zu uns zurück!\"" },
      { number: 16, text: "Da kehrte der König zurück und kam bis an den Jordan. Die Männer von Juda waren ihm bis Gilgal entgegengekommen, um ihn über den Jordan zu geleiten." },
      { number: 17, text: "Schimi Ben-Gera, der Benjaminit aus Bahurim, eilte zusammen mit den Männern von Juda herbei, um David zu empfangen." },
      { number: 18, text: "Tausend Männer waren mit ihm gekommen, darunter auch Ziba, der Gefolgsmann Sauls, mit seinen fünfzehn Söhnen und zwanzig Dienern. Noch bevor der König kam, waren sie durch den Jordan gewatet" },
      { number: 19, text: "und halfen nun, den ganzen Haushalt des Königs über den Fluss zu führen und alles zu tun, was der König für gut hielt. Als David gerade den Jordan überqueren wollte, fiel Schimi Ben-Gera vor ihm nieder." },
      { number: 20, text: "Er sagte zum König: \"Bitte, mein Herr, rechne mir die Schuld nicht an und denk nicht mehr daran, wie ich, dein Diener, mich verfehlt habe, als mein Herr und König aus Jerusalem auszog. Der König möge es sich nicht zu Herzen nehmen!" },
      { number: 21, text: "Denn dein Diener hat erkannt: 'Ja, ich habe gesündigt!' Halte es mir bitte zugute, dass ich heute als Erster vom Haus Josefs gekommen bin, um meinen Herrn, den König, zu empfangen.\"" },
      { number: 22, text: "Da erwiderte Abischai Ben-Zeruja: \"Soll Schimi etwa nicht getötet werden? Er hat doch den Gesalbten Jahwes verflucht!\"" },
      { number: 23, text: "David aber sagte: \"In was wollt ihr mich da hineinziehen, ihr Söhne der Zeruja? Wollt ihr heute als Ankläger auftreten? Soll heute ein Mann in Israel getötet werden? Weiß ich denn nicht, dass ich heute König über Israel geworden bin?\"" },
      { number: 24, text: "Der König sagte zu Schimi: \"Du musst nicht sterben!\" Und er schwor es ihm." },
      { number: 25, text: "Auch Mefi-Boschet, der Nachkomme Sauls, kam dem König entgegen. Seit dem Tag, als der König weggegangen war, bis zum Tag, an dem er in Frieden zurückkehren würde, hatte er seine Füße nicht zurechtgemacht, seinen Bart nicht gepflegt und seine Kleidung nicht gewaschen." },
      { number: 26, text: "Als er dem König von Jerusalem aus entgegen kam, sagte dieser zu ihm: \"Warum bist du nicht mit mir gekommen, Mefi-Boschet?\"" },
      { number: 27, text: "\"Mein Herr und König\", erwiderte dieser, \"mein Diener hat mich betrogen! Denn dein Diener hatte sich gesagt: 'Ich will mir den Esel satteln lassen und mit dem König ziehen!' Dein Diener ist ja gelähmt." },
      { number: 28, text: "Aber der da hat deinen Diener bei meinem Herrn und König verleumdet. Doch mein Herr, der König, ist wie der Engel Gottes. Tu mit mir, was du für richtig hältst!" },
      { number: 29, text: "Alle, die zu meinem Vaterhaus gehören, hätten damit rechnen müssen, von dir getötet zu werden. Doch du hast deinen Diener zu denen gesetzt, die an deinem Tisch essen. Welches Recht hätte ich denn, noch etwas vom König zu erbitten?\"" },
      { number: 30, text: "Da sagte der König zu ihm: \"Was redest du noch von deiner Sache? Ich bestimme, dass du mit Ziba den Landbesitz teilst.\"" },
      { number: 31, text: "\"Er kann ruhig alles nehmen!\", erwiderte Mefi-Boschet dem König. \"Hauptsache ist, dass mein Herr und König in Frieden wieder nach Hause gekommen ist!\"" },
      { number: 32, text: "Barsillai war aus Roglim in Gilead gekommen und mit dem König bis an den Jordan gegangen, um ihn dort zu verabschieden." },
      { number: 33, text: "Er war ein sehr reicher Mann und hatte den König versorgt, als dieser sich in Mahanajim aufhielt. Mit seinen 80 Jahren war er aber schon sehr alt." },
      { number: 34, text: "Der König sagte zu ihm: \"Geh mit mir hinüber, und ich werde dich bei mir in Jerusalem versorgen!\"" },
      { number: 35, text: "Doch Barsillai erwiderte: \"Wie lange habe ich wohl noch zu leben, dass ich mit dem König nach Jerusalem hinaufziehen sollte?" },
      { number: 36, text: "Ich bin heute schon 80 Jahre alt, da macht es keinen Unterschied mehr, ob etwas gut oder schlecht für mich ist. Kann dein Diener denn noch schmecken, was er isst oder trinkt? Kann ich etwa noch auf die Stimmen der Sänger und Sängerinnen hören? Wozu sollte ich meinem Herrn und König noch zur Last fallen?" },
      { number: 37, text: "Nur für kurze Zeit könnte dein Diener mit dem König über den Jordan gehen. Warum sollte der König mir das so reich vergelten?" },
      { number: 38, text: "Lass mich umkehren und in meiner Stadt sterben, beim Grab meines Vaters und meiner Mutter! Aber schau, hier ist dein Diener Kimham! Der mag mit meinem Herrn und König hinübergehen. Tu an ihm, was du für richtig hältst!\"" },
      { number: 39, text: "\"Gut\", sagte der König, \"Kimham soll mit mir hinübergehen und ich werde für ihn tun, was du willst. Und wenn du noch etwas von mir möchtest, will ich es gern für dich tun!\"" },
      { number: 40, text: "Davids Truppen waren schon über den Jordan gezogen. Nun ging auch der König hinüber, nachdem er Barsillai geküsst und gesegnet hatte. Barsillai kehrte nach Hause zurück." },
      { number: 41, text: "Der König zog weiter nach Gilgal. Kimham ging mit ihm. Das ganze Volk von Juda und die Hälfte des Volkes Israel gaben dem König das Geleit." },
      { number: 42, text: "Da kamen die Männer von Israel zum König und beschwerten sich. \"Weshalb haben unsere Brüder, die Männer von Juda, dich gestohlen?\", sagten sie. \"Warum durften sie den König und seine Familie und alle seine Leute über den Jordan führen?\"" },
      { number: 43, text: "Die Männer Judas erwiderten den Männern Israels: \"Weil uns der König näher steht! Warum regt ihr euch darüber auf? Haben wir etwa ein Stück vom König gegessen, oder hat er uns irgendein Geschenk gemacht?\"" },
      { number: 44, text: "Aber die Männer von Israel erwiderten: \"Wir haben zehn Anteile am König, und auch an David haben wir einen größeren Anteil als ihr! Warum habt ihr uns übergangen? Haben wir nicht zuerst daran gedacht, den König zurückzuholen?\" Da wurde das Reden der Männer von Juda noch härter als das der Israeliten." },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Nun gab es dort gerade einen niederträchtigen Benjaminiten namens Scheba Ben-Bichri. Er blies das Signalhorn und rief:\"Was geht uns dieser David an? / Seit wann gehört Ben-Isai zu uns? / Auf, nach Hause, Männer Israels!\"", heading: "Schebas Aufstand" },
      { number: 2, text: "Da liefen alle Männer Israels von David zu Scheba Ben-Bichri über. Die Männer Judas aber hielten an ihrem König fest und geleiteten ihn vom Jordan bis nach Jerusalem." },
      { number: 3, text: "So kam David in sein Haus nach Jerusalem. Dort befahl er, die zehn Nebenfrauen, die er zum Hüten des Palastes zurückgelassen hatte, in ein bewachtes Haus zu bringen. Er ließ sie gut versorgen, schlief aber nicht mehr mit ihnen. Bis zu ihrem Tod blieben sie eingeschlossen als Witwen zu Lebzeiten des Mannes." },
      { number: 4, text: "Dann sagte der König zu Amasa: \"Biete mir die Männer von Juda auf! Drei Tage, dann bist du hier zur Stelle!\"" },
      { number: 5, text: "Amasa ging, um die Männer Judas zusammenzurufen. Aber er überzog die Frist, die David ihm gesetzt hatte." },
      { number: 6, text: "Da sagte David zu Abischai: \"Jetzt wird uns Scheba Ben-Bichri noch gefährlicher als Abschalom. Nimm du meine Leute und verfolge ihn, damit er keine Festungsstädte für sich gewinnt und uns empfindlich schadet.\"" },
      { number: 7, text: "Da zogen die Männer Joabs, die Leibgarde und die Elitetruppe mit Abischai los. Sie verließen Jerusalem, um Scheba Ben-Bichri zu verfolgen." },
      { number: 8, text: "Als sie den großen Stein bei Gibeon erreichten, kam Amasa ihnen entgegen. Joab trug wie gewöhnlich seinen Waffenrock. Darüber hatte er einen Stoffgürtel gebunden, in dem sein Kurzschwert mit Scheide befestigt war. Wenn er vortrat, glitt dieses heraus." },
      { number: 9, text: "Joab sagte nun zu Amasa: \"Geht es dir gut, mein Bruder?\" Dabei fasste er ihn mit der rechten Hand am Bart, um ihn zu küssen." },
      { number: 10, text: "Amasa hatte aber nicht auf das Schwert geachtet, das Joab in der anderen Hand hielt. Damit stieß dieser ihn so in den Bauch, dass seine Eingeweide auf die Erde quollen. Ein zweites Mal war nicht nötig. So starb er. Dann jagten Joab und sein Bruder Abischai weiter hinter Scheba Ben-Bichri her." },
      { number: 11, text: "Einer von Joabs Leuten blieb bei Amasa stehen und rief: \"Wer es mit Joab hält und für David ist, los, Joab nach!\"" },
      { number: 12, text: "Amasa wälzte sich in seinem Blut mitten auf dem Weg. Als der Mann sah, dass die Soldaten stehen blieben, schaffte er Amasa auf die Seite ins Feld und warf ein Kleidungsstück über ihn, damit nicht jeder, der vorbeikam, stehen blieb." },
      { number: 13, text: "Als er ihn so beiseite geschafft hatte, folgten alle Joab und nahmen die Verfolgung Schebas wieder auf." },
      { number: 14, text: "Dieser durchzog alle Stämme Israels bis nach Abel und Bet-Maacha*. Doch nur die Berim* hatten sich ihm angeschlossen.", footnotes: ["Abel und Bet-Maacha. Stadt ganz im Norden Israels, die wahrscheinlich aus zwei Ortsteilen bestand.", "Berim. Das Wort kommt nur hier in der Bibel vor. Seine Bedeutung ist bis heute unbekannt."] },
      { number: 15, text: "Als Joab und seine Soldaten Abel-Bet-Maacha erreicht hatten, schlossen sie Scheba darin ein und schütteten eine Angriffsrampe gegen die Stadt auf, die zuletzt bis an die Vormauer stieß. Gleichzeitig unterwühlten sie die Hauptmauer, um sie zum Einsturz zu bringen." },
      { number: 16, text: "Da rief eine kluge Frau aus der Stadt den Belagerern zu: \"Hallo, hört her! Hört her! Sagt Joab, er soll herkommen, ich muss mit ihm reden!\"" },
      { number: 17, text: "Als er näher herankam, fragte die Frau: \"Bist du Joab?\" – \"Ja, der bin ich\", erwiderte er. Da sagte sie zu ihm: \"Bitte hör die Worte deiner Dienerin an!\" – \"Ich höre\", erwiderte Joab." },
      { number: 18, text: "Sie begann: \"Früher pflegte man zu sagen: 'Man frage nur in Abel, schon ist man am Ziel!'" },
      { number: 19, text: "Meine Stadt gehört zu den Friedlichen und Treuen in Israel. Warum willst du diese Stadt, eine Mutter in Israel, töten? Warum willst du ein Erbstück Jahwes verschlingen?\"" },
      { number: 20, text: "\"Auf gar keinen Fall will ich verschlingen und vernichten\", erwiderte Joab." },
      { number: 21, text: "\"So ist die Sache nicht! Es geht nur um einen Mann aus dem Bergland von Efraïm. Er heißt Scheba Ben-Bichri und hat sich gegen den König, gegen David erhoben. Wenn ihr ihn herausgebt, ziehe ich von der Stadt ab.\" – \"Gut\", sagte die Frau, \"man wird dir seinen Kopf über die Mauer werfen\"." },
      { number: 22, text: "Mit ihrer Weisheit überzeugte sie die Leute in der Stadt. Sie schlugen Scheba Ben-Bichri den Kopf ab und warfen ihn zu Joab über die Mauer. Da blies dieser das Signalhorn, und seine Männer brachen die Belagerung ab. Jeder ging wieder nach Hause, und Joab kehrte zum König nach Jerusalem zurück." },
      { number: 23, text: "Joab war der Oberbefehlshaber über das Heer Israels, Benaja Ben-Jojada befehligte die königliche Leibgarde,", heading: "Davids oberste Beamte" },
      { number: 24, text: "Adoram hatte die Aufsicht über die Zwangsarbeiter, Joschafat Ben-Ahilud war Kanzler," },
      { number: 25, text: "Schewa Staatsschreiber, Zadok und Abjatar waren Priester." },
      { number: 26, text: "Auch Ira aus Jaïr war Priester in Davids Diensten." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Während der Regierungszeit Davids gab es einmal eine schwere Hungersnot, die drei Jahre lang dauerte. Da suchte David die Gegenwart Jahwes, und Jahwe nannte ihm den Grund: \"Es ist wegen der Blutschuld, die auf Saul und seinem Haus lastet, weil er so viele Gibeoniten umgebracht hat.\"", heading: "21-24: Davids letzte Kämpfe und Anordnungen\nDie Sühnung einer Blutschuld von König Saul" },
      { number: 2, text: "Die Gibeoniten gehörten nicht zu Israel, sondern zum Rest der Amoriter im Land. Die Israeliten hatten ihnen geschworen, sie zu verschonen.* Aber Saul in seinem Eifer für Israel und Juda hatte versucht, sie alle umzubringen. David ließ die Gibeoniten herbeirufen", footnotes: ["sie zu verschonen. Siehe Josua 9,15!"] },
      { number: 3, text: "und fragte sie: \"Was soll ich für euch tun? Womit kann ich Sühne leisten, damit ihr das Erbe Jahwes segnet?\"" },
      { number: 4, text: "Die Gibeoniten erwiderten: \"Es geht uns nicht um das Silber und Gold der Nachkommen Sauls, und es ist uns auch nicht erlaubt, jemand in Israel zu töten.\" – \"Was soll ich dann für euch tun?\", fragte David." },
      { number: 5, text: "Sie erwiderten: \"Von dem Mann, der geplant hat, uns auszurotten, der uns vernichten wollte, sodass wir in Israel keinen Platz mehr zum Leben gehabt hätten," },
      { number: 6, text: "aus dessen Nachkommenschaft liefere man uns sieben Männer aus. Wir wollen sie vor Jahwe hinrichten und zwar in Gibea, der Heimatstadt Sauls, dem Erwählten Jahwes.\" Der König sagte: \"Ich will sie euch geben.\"" },
      { number: 7, text: "Er verschonte jedoch Mefi-Boschet, den Sohn Jonatans und Enkel Sauls, weil er Jonatan, dem Sohn Sauls, vor Jahwe geschworen hatte, seine Nachkommen nicht auszurotten." },
      { number: 8, text: "So nahm der König die beiden Söhne, die Rizpa Bat-Aja Saul geboren hatte: Armoni und Mefi-Boschet, und die fünf Söhne der Saulstochter Merab, die sie Adriel Ben-Barsillai aus Mehola geboren hatte." },
      { number: 9, text: "Er lieferte sie den Gibeoniten aus. Alle sieben wurden am selben Tag auf dem Berg vor Jahwe hingerichtet. So starben sie in den ersten Tagen der Erntezeit, die Gerstenernte hatte gerade begonnen." },
      { number: 10, text: "Da nahm Rizpa Bat-Aja Sackleinwand, breitete sie auf dem Felsen aus und setzte sich darauf. Sie blieb dort vom Beginn der Ernte, bis der erste Regen fiel. Tagsüber verscheuchte sie die Vögel und nachts hielt sie die wilden Tiere von den Leichen fern." },
      { number: 11, text: "Als David hörte, was Rizpa Bat-Aja, die Nebenfrau Sauls, tat," },
      { number: 12, text: "ging David nach Jabesch in Gilead und ließ sich die Gebeine von Saul und dessen Sohn Jonatan aushändigen. Die Bürger von Jabesch in Gilead hatten sie einst vom Markt in Bet-Schean gestohlen, wo die Philister sie nach ihrem Sieg auf dem Gilboa aufgehängt hatten.*", footnotes: ["aufgehängt hatten. Siehe 1. Samuel 31,11-12!"] },
      { number: 13, text: "Als David die Gebeine Sauls und seines Sohnes Jonatan überführt hatte, ließ er die Gebeine der Hingerichteten einsammeln" },
      { number: 14, text: "und alle zusammen in Zela im Gebiet von Benjamin im Grab von Sauls Vater Kisch beisetzen. Danach ließ Gott sich für das Land erbitten." },
      { number: 15, text: "Wieder einmal kam es für Israel zu einer Schlacht mit den Philistern. David zog ihnen mit seinem Heer entgegen und kämpfte gegen sie. Als er vom Kampf ermüdet war,", heading: "Davids Helden und ihre Taten" },
      { number: 16, text: "griff ihn Jischbi-Benob an und wollte ihn erschlagen. Allein das Gewicht seiner Lanzenspitze aus Bronze betrug dreieinhalb Kilogramm* und er trug eine neue Rüstung.", footnotes: ["3,5 Kilogramm. Wörtlich: 300 Schekel (= 3450 Gramm)."] },
      { number: 17, text: "Doch Abischai Ben-Zeruja kam David zu Hilfe und erschlug den Philister. Damals beschworen Davids Männer den König: \"Du darfst nicht wieder mit uns in den Kampf ziehen, denn wenn wir dich verlieren, erlischt die Leuchte Israels.\"" },
      { number: 18, text: "Später kam es bei Gob* wieder zum Kampf mit den Philistern. Damals erschlug Sibbechai aus Huscha den Saf*, der zu den Nachkommen des Rafa* gehörte.", footnotes: ["Gob lag vermutlich in der Nähe von Geser, wo 1. Chronik 20,4 denselben Kampf lokalisiert, 27 km südöstlich von Joppe.", "Saf. In 1. Chronik 20,4wird er Sippai genannt.", "Rafa gilt als Stammvater der Refaïter, das sind Riesen."] },
      { number: 19, text: "Bei einem weiteren Kampf in Gob erschlug der Weber Elhanan Ben-Jaïr aus Bethlehem* den Philister Goliat aus Gat, dessen Speer so dick wie ein Weberbaum* war.", footnotes: ["Bethlehem. Es ist möglich, dass ein Kopist hier die im Hebräischen ähnlichen Worte für \"Lahmi, den Bruder von Goliat\" (wie in 1. Chronik 20,5) mit \"der Bethlehemit Goliat\" verwechselt hat.", "Weberbaum. So hießen die Querstangen an den beiden Enden des Webstuhls, an denen die Kettfäden befestigt wurden. Sie mussten eine beträchtliche Dicke haben."] },
      { number: 20, text: "Wieder kam es zum Kampf bei Gat. Da trat ein streitsüchtiger Mann hervor, der an jeder Hand sechs Finger und an jedem Fuß sechs Zehen hatte, insgesamt also 24. Auch er war ein Nachkomme Rafas." },
      { number: 21, text: "Er verhöhnte Israel. Da erschlug ihn Jonatan Ben-Schima, der Neffe Davids." },
      { number: 22, text: "Diese vier waren Nachkommen von Rafa in Gat und wurden von David und seinen Männern erschlagen." },
    ] },
    { number: 22, verses: [
      { number: 1, text: "David dichtete dieses Lied* für Jahwe, nachdem dieser ihn vor Saul und allen anderen Feinden gerettet hatte. An dem Tag sang er:", heading: "Davids Danklied", footnotes: ["Das Lied ist auch in Psalm 18 überliefert."] },
      { number: 2, text: "Jahwe, mein Fels, mein Schutz und mein Retter," },
      { number: 3, text: "mein Gott, meine Burg, in der ich mich berge, / mein Schild und mein sicheres Heil! / Er ist mir Zuflucht und hochragende Festung, / mein Retter, der mich schützt vor Gewalt." },
      { number: 4, text: "Ich rufe: \"Jahwe sei gelobt!\" / Schon bin ich von meinen Feinden befreit." },
      { number: 5, text: "Ich war in den Fesseln des Todes gefangen, / Sturzbäche des Unheils erschreckten mich." },
      { number: 6, text: "Mit Stricken des Todes war ich gebunden, / die Todesfalle schlug über mir zu." },
      { number: 7, text: "Ich rief zu Jahwe in meiner Angst, / schrie um Hilfe zu meinem Gott.Er hörte mich in seinem Tempel, / mein Hilfeschrei drang an sein Ohr." },
      { number: 8, text: "Da wankte und schwankte die Erde, / die Grundlagen des Himmels erbebten. / Sie zitterten, denn er wurde zornig." },
      { number: 9, text: "Rauch stieg auf von seiner Nase / und Feuer schoss aus seinem Mund, / glühende Kohlen sprühten hervor." },
      { number: 10, text: "Er neigte den Himmel tief auf die Erde / und fuhr auf dunklen Wolken herab." },
      { number: 11, text: "Er flog auf einem Cherub*, / er schwebte auf den Schwingen des Sturms.", footnotes: ["Cherub (Mehrzahl: Cherubim): Majestätisches (Engel-)Wesen, das Gottes Herrlichkeit repräsentiert."] },
      { number: 12, text: "Er hüllte sich in Finsternis wie in ein Zelt, / in Regendunkel und schwarzes Gewölk." },
      { number: 13, text: "Durch seinen Glanz flammten Kohlen glühend auf." },
      { number: 14, text: "Im Himmel ließ Jahwe den Donner grollen, / laut dröhnte die Stimme des Höchsten." },
      { number: 15, text: "Er schoss seine Pfeile und verjagte die Feinde, / er schleuderte Blitze und verwirrte sie." },
      { number: 16, text: "Da zeigte sich der Grund der Gewässer, / die Fundamente der Welt wurden entblößt / vor dem Drohen Jahwes, / vor dem Schnauben seines zornigen Atems." },
      { number: 17, text: "Aus der Höhe griff seine Hand nach mir, / fasste mich und zog mich aus der Flut." },
      { number: 18, text: "Er entriss mich den mächtigen Feinden, / die stärker waren als ich und mich hassten." },
      { number: 19, text: "Sie überfielen mich am Tag meines Unglücks, / doch Jahwe wurde mein Halt." },
      { number: 20, text: "Er führte mich hinaus ins Weite, / befreite mich, weil er mich mochte." },
      { number: 21, text: "Jahwe hat mir meine Treue vergolten, / mich nach der Reinheit meiner Hände beschenkt." },
      { number: 22, text: "Denn ich hielt mich an die Wege Jahwes, / fiel nicht schuldig von meinem Gott ab." },
      { number: 23, text: "Seine Gebote standen mir immer vor Augen, / seine Befehle wies ich nicht von mir weg." },
      { number: 24, text: "Ich lebte ohne Tadel vor ihm / und nahm mich vor der Sünde in acht." },
      { number: 25, text: "So hat Jahwe mir meine Treue vergolten, / denn meine Hände waren rein." },
      { number: 26, text: "Einem Gütigen zeigst du dich gütig, / einem treuen Mann treu." },
      { number: 27, text: "Dem Reinen zeigst du dich rein, / doch dem Falschen bist du verdreht." },
      { number: 28, text: "Ja, du rettest das demütige Volk, / doch stolze Menschen zwingst du nieder." },
      { number: 29, text: "Ja, du bist meine Leuchte, Jahwe. / Jahwe macht das Dunkel mir hell." },
      { number: 30, text: "Ja, mit dir überrenn ich ein Heer, / mit meinem Gott überspring ich die Mauer." },
      { number: 31, text: "Ja, Gott – sein Weg ist tadellos, / Jahwes Wort ist unverfälscht. / Ein Schild ist er für alle, / die Schutz bei ihm suchen." },
      { number: 32, text: "Ja, wer ist Gott, wenn nicht Jahwe! / Wer ist ein Fels, wenn nicht unser Gott!" },
      { number: 33, text: "Dieser Gott ist meine Festung, / er macht meinen Weg tadellos." },
      { number: 34, text: "Er macht meine Füße gazellenflink / und standfest auf allen Höhen." },
      { number: 35, text: "Er lehrt meine Hände das Kämpfen / und meine Arme, den Bogen zu spannen." },
      { number: 36, text: "Du gabst mir den Schild deines Heils, / und dein Zuspruch machte mich groß! /" },
      { number: 37, text: "Du schafftest Raum meinen Schritten, / meine Knöchel blieben fest." },
      { number: 38, text: "Ich jagte meinen Feinden nach und überwältigte sie. / Erst als sie vernichtet waren, kehrte ich um." },
      { number: 39, text: "Zerschmettert habe ich sie, / sie stehen nicht wieder auf. / Tot fielen sie vor meine Füße." },
      { number: 40, text: "Du versorgtest mich mit Kraft zum Kampf, / zwangst meine Gegner unter mich nieder." },
      { number: 41, text: "Du hast meine Feinde zur Flucht gezwungen, / ich konnte meine Hasser vernichten." },
      { number: 42, text: "Sie blickten umher, aber da war kein Retter, / zu Jahwe, doch er hörte sie nicht." },
      { number: 43, text: "Ich zerrieb sie wie Staub auf der Erde, / zerstampfte sie wie Straßendreck." },
      { number: 44, text: "Du hast mich den Streitigkeiten des Volkes entrissen, / hast mich zum Haupt über Völker gesetzt. / Ein Volk, das ich nicht kannte, dient mir." },
      { number: 45, text: "Ausländer kamen und krochen vor mir. / Sie hörten mir zu und gehorchten sofort." },
      { number: 46, text: "Zitternd kamen sie aus ihren Burgen / und gaben ihren Widerstand auf." },
      { number: 47, text: "Jahwe lebt! Gepriesen sei mein Fels, / erhoben der Gott meines Heils!" },
      { number: 48, text: "Denn Gott hat mir Rache verschafft, / hat mir die Völker unterworfen /" },
      { number: 49, text: "und mich meinen Feinden entrissen. / Du hast mich über meine Gegner erhoben, / mich vom Mann der Gewalttat befreit." },
      { number: 50, text: "Darum will ich dich loben, Jahwe, / deinen Ruhm vor den Völkern besingen,*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 15,9."] },
      { number: 51, text: "der seinem König große Siege verschafft, / der seinem Gesalbten Gnade erweist, / David und seinem Nachwuchs für immer." },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Dies sind die letzten Aussagen Davids:\"Das sagt David Ben-Isai, / so spricht der hochgestellte Mann, / der Gesalbte des Gottes Jakobs, / der Israels Lieder singt und spielt.", heading: "Davids Vermächtnis" },
      { number: 2, text: "Der Geist Jahwes hat durch mich gesprochen, / seine Rede war in meinem Mund." },
      { number: 3, text: "Israels Gott hat geredet, / Israels Fels sprach zu mir: / 'Wer gerecht über die Menschen herrscht, / wer das in Ehrfurcht vor Gott tut," },
      { number: 4, text: "der ist wie das Morgenlicht, / wenn die Sonne aufstrahlt, / wenn ihr Glanz den Nebel vertreibt, / wenn das Grün aus regennasser Erde sprosst.'" },
      { number: 5, text: "Steht nicht so mein Königshaus zu Gott? / Für alle Zeit hat er mir einen Bund gesetzt, / hat alles wohl geordnet, gut verwahrt. / Ja, all mein Heil und all meine Freude, / er ließ sie wachsen." },
      { number: 6, text: "Doch wer von Gott nichts wissen will, / ist wie abgestorbenes Dornengestrüpp, / entwurzelt und vom Wind verweht. / Mit bloßen Händen fasst es niemand an." },
      { number: 7, text: "Mit Eisen und Speerschaft wird es gepackt / und ins Feuer geworfen, wo es gründlich verbrennt.\"" },
      { number: 8, text: "Es folgen die Namen der Elitetruppe Davids: Jischbaal aus der Sippe Hachmoni, Anführer der Wagenkämpfer*. Er schwang seinen Speer über 800 Mann, die er in einer Schlacht durchbohrte.", heading: "Davids Elitetruppe", footnotes: ["Wagenkämpfer. Wörtlich: der Dritten. Das war eine feststehende Bezeichnung für den dritten Mann auf dem Streitwagen, einem Offizier."] },
      { number: 9, text: "Der zweite nach ihm war Eleasar Ben-Dodo, ein Nachkomme Ahoachs. Er war einer der drei, die David bei sich hatte, als sie die Philister verhöhnten, die sich dort zum Kampf versammelt hatten. Als die Männer Israels sich zurückzogen," },
      { number: 10, text: "stand er aufrecht und schlug auf die Philister ein, bis sein Arm erlahmte und seine Hand am Schwert kleben blieb. So schenkte Jahwe damals einen großen Sieg, und die Kämpfer kehrten um, ihm nach, doch nur noch, um zu plündern." },
      { number: 11, text: "Der dritte war Schamma Ben-Age aus Harar. Die Philister hatten sich zu einer Truppe gesammelt, und das Volk floh vor ihnen. Nun gab es dort ein Linsenfeld." },
      { number: 12, text: "Schamma stellte sich mitten in das Feldstück, entriss es den Philistern und schlug sie. So schaffte Jahwe eine große Rettung." },
      { number: 13, text: "Drei von den dreißig Helden Davids kamen einmal zu David in die Höhle bei Adullam*. Es war in der Erntezeit, und die Philister hatten die Ebene Refaïm* besetzt.", footnotes: ["Adullam, \"Schlupfwinkel\", Stadt in der Schefela, dem Hügelland von Juda, 26 km westlich von Jerusalem.", "Refaïm. Fruchtbares Gebiet westlich von Jerusalem."] },
      { number: 14, text: "Auch in Bethlehem lagen sie. David hielt sich gerade in der Bergfestung auf," },
      { number: 15, text: "als ihn ein großes Verlangen überkam. Er sagte: \"Wer bringt mir Wasser aus der Zisterne am Tor von Bethlehem?\"" },
      { number: 16, text: "Da drangen die drei Helden ins Lager der Philister ein, schöpften Wasser aus der Torzisterne von Bethlehem und brachten es David. Doch David wollte es nicht trinken, sondern goss es als Trankopfer vor Jahwe aus." },
      { number: 17, text: "Er sagte: \"Jahwe bewahre mich davor, so etwas zu tun! Es ist das Blut der Männer, die unter Lebensgefahr dort hingegangen sind.\" Deshalb wollte er es nicht trinken. Das hatten die drei Helden getan." },
      { number: 18, text: "Abischai Ben-Zeruja, der Bruder Joabs, war der Anführer der Dreißig und hochgeachtet unter ihnen. Er tötete 300 Feinde mit dem Speer" },
      { number: 19, text: "und war angesehener als die Dreißig, aber an die Drei reichte er nicht heran." },
      { number: 20, text: "Benaja Ben-Jojada war ein tapferer Mann, der große Taten vollbrachte. Er erschlug die beiden Kriegshelden von Moab. Und an einem Schneetag stieg er in eine Zisterne und erschlug den Löwen, der dort hineingeraten war." },
      { number: 21, text: "Er war es auch, der den gewaltigen mit einem Speer bewaffneten Ägypter erschlug. Mit einem Stock ging er zu dem Ägypter hinunter, riss ihm den Speer aus der Hand und durchbohrte ihn damit." },
      { number: 22, text: "Solche Taten vollbrachte Benaja Ben-Jojada. Er war hochgeachtet unter den dreißig Helden" },
      { number: 23, text: "und wurde mehr als sie geehrt. Aber an die Drei reichte er nicht heran. David machte ihn zum Anführer seiner Leibgarde." },
      { number: 24, text: "Zu den Dreißig gehörten Joabs Bruder Asaël, Elhanan Ben-Dodo aus Bethlehem," },
      { number: 25, text: "Schamma und Elika aus Harod," },
      { number: 26, text: "Helez aus Bet-Pelet, Ira Ben-Ikkesch aus Tekoa," },
      { number: 27, text: "Abieser aus Anatot, Mebunnai* aus Huscha,", footnotes: ["Mebunnai. In 21,18und 1. Chronik 11,29 wird er Sibbechai genannt."] },
      { number: 28, text: "Zalmon aus Ahoach, Mahrai aus Netofa," },
      { number: 29, text: "Heled Ben-Baana, ebenfalls aus Netofa, Ittai Ben-Ribai aus dem Gibea der Benjaminiten," },
      { number: 30, text: "Benaja aus Piraton, Hiddai aus Nahale-Gasch," },
      { number: 31, text: "Abialbon aus Bet-Araba, Asmawet aus Bahurim," },
      { number: 32, text: "Eljachba aus Schaalbon und Jonatan von den Söhnen Jaschens," },
      { number: 33, text: "Schamma aus Harar, Ahiam Ben-Scharar aus Arar," },
      { number: 34, text: "Elifelet Ben-Ahasbai aus Maacha, Eliam Ben-Ahitofel aus Gilo," },
      { number: 35, text: "Hezro aus Karmel, Paarai aus Arab," },
      { number: 36, text: "Jigal Ben-Natan aus Zoba, Bani aus Gad," },
      { number: 37, text: "der Ammoniter Zelek, Nachrai aus Beerot, der Waffenträger von Joab Ben-Zeruja," },
      { number: 38, text: "Ira und Gareb aus Jattir" },
      { number: 39, text: "und der Hetiter Urija, zusammen 37." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Da flammte der Zorn Jahwes wieder gegen Israel auf. Er verleitete David, Israel und Juda zu zählen, und zwar zum Schaden seines Volkes.", heading: "Davids Volkszählung" },
      { number: 2, text: "Der König sagte also zu Joab, seinem Heerführer, der gerade bei ihm war: \"Zieh doch durch alle Stämme Israels, von Dan bis Beerscheba, und lass die wehrfähigen Männer zählen. Ich will wissen, wie viele es sind.\"" },
      { number: 3, text: "Doch Joab sagte zum König: \"Jahwe, dein Gott, möge das Volk noch hundertmal zahlreicher machen, als es schon ist, und dass du es noch mit eigenen Augen siehst, mein Herr und König! Aber warum nur willst du so etwas tun?\"" },
      { number: 4, text: "Doch der König blieb bei seinem Entschluss. Er ließ sich von Joab und den Heerführern nicht davon abbringen. So zog Joab mit seinen Offizieren vor dem König los, um das Volk Israel zu zählen." },
      { number: 5, text: "Sie gingen über den Jordan und begannen bei Aroer, der Stadt, die mitten im Arnontal liegt, gingen dann auf das Stammesgebiet von Gad zu und kamen nach Jaser*.", footnotes: ["Jaser. Vermutlich Khirbet es-Sar, 10 km westlich vom heutigen Amman."] },
      { number: 6, text: "Sie zogen weiter durch Gilead* bis in die Gegend von Tachtim-Hodschi*. Über Dan und Ijon* kamen sie in die Gegend von Sidon*.", footnotes: ["Gilead bezeichnet hier das mittlere Ostjordanland.", "Tachtim-Hodschi. Vermutlich handelt es sich um eine Gegend im Norden von Israel. Beide Begriffe kommen nur an dieser Stelle vor und sind unbekannt.", "Dan und Ijon. Die Städte liegen ganz im Norden Israels.", "Sidon war die wichtigste Hafenstadt in Phönizien, heute Saida im Libanon."] },
      { number: 7, text: "Dann kamen sie zur befestigten Stadt Tyrus, den Städten der Hiwiter und Kanaaniter und zogen in den Süden von Juda nach Beerscheba." },
      { number: 8, text: "So durchstreiften sie das ganze Land. Nach Ablauf von neun Monaten und zwanzig Tagen kamen sie nach Jerusalem zurück." },
      { number: 9, text: "Joab teilte dem König das Ergebnis der Musterung mit: die Gesamtzahl der wehrfähigen Männer, die mit dem Schwert umgehen konnten, betrug in Israel 800.000 und in Juda 500.000." },
      { number: 10, text: "Aber jetzt schlug David das Gewissen, weil er das Volk gezählt hatte, und er sagte zu Jahwe: \"Ich habe mich schwer versündigt mit dem, was ich getan habe. Jahwe, vergib doch bitte die Schuld deines Dieners. Ich habe sehr unbesonnen gehandelt.\"", heading: "Gottes Gericht: die Pest" },
      { number: 11, text: "Als David am Morgen aufstand, kam das Wort Jahwes zu dem Propheten Gad, dem Seher Davids:" },
      { number: 12, text: "\"Geh zu David und richte ihm aus: 'So spricht Jahwe: Dreierlei lege ich dir vor. Wähl dir aus, was ich dir antun soll!'\"" },
      { number: 13, text: "Gad kam zu David und überbrachte die Botschaft. \"Soll dir eine siebenjährige* Hungersnot ins Land kommen?\", fragte er. \"Oder willst du drei Monate vor deinen Verfolgern fliehen? Oder soll drei Tage lang die Pest in deinem Land wüten? Überleg es dir gut und sag mir, welche Antwort ich dem überbringen soll, der mich gesandt hat.\"", footnotes: ["siebenjährige. In 2. Samuel (1. Chronik 21,12: dreijährige) wird wahrscheinlich die dreijährige Hungersnot, die gerade vergangen war (2. Samuel 21,1), mitgezählt und wegen der inklusiven Zählweise der Juden (das aktuelle Jahr zählt mit) ergibt das zusammen mit den angedrohten drei Jahren insgesamt sieben Jahre Hungersnot."] },
      { number: 14, text: "David sagte zu Gad: \"Ich habe große Angst. Dann will ich lieber in die Hand Jahwes fallen, denn sein Erbarmen ist groß. In die Hand von Menschen will ich nicht geraten.\"" },
      { number: 15, text: "Da ließ Jahwe die Pest in Israel ausbrechen. Sie wütete von jenem Morgen an bis zu der von ihm bestimmten Zeit. Vom ganzen Volk zwischen Dan und Beerscheba starben 70.000 Mann." },
      { number: 16, text: "Als der Engel im Begriff stand, sein grausiges Werk auch in Jerusalem zu tun und die Stadt zu vernichten, hatte Jahwe Mitleid. Er sagte dem Engel, der seine Opfer unter dem Volk suchte: \"Genug! Hör auf damit!\" Der Engel Jahwes stand gerade am Dreschplatz von Arauna, einem Jebusiter." },
      { number: 17, text: "Als David den Engel sah, der die Leute umbrachte, sagte er zu Jahwe: \"Ich habe doch gesündigt! Ich habe verkehrt gehandelt! Was haben denn diese Schafe getan? Bestrafe doch mich und meine Familie!\"" },
      { number: 18, text: "An diesem Tag kam Gad zu David und sagte zu ihm: \"Geh hinauf zum Dreschplatz des Jebusiters Arauna und errichte dort einen Altar für Jahwe!\"", heading: "David baut einen Altar auf dem Dreschplatz" },
      { number: 19, text: "Da zog David nach dem Befehl Jahwes, der durch Gad zu ihm gekommen war, hinauf." },
      { number: 20, text: "Als Arauna hinausblickte und den König mit seinem Gefolge zu sich kommen sah, ging er hinaus und warf sich vor ihm nieder, mit dem Gesicht zur Erde." },
      { number: 21, text: "Er fragte: \"Weshalb kommt mein Herr und König zu seinem Diener?\" – \"Um den Dreschplatz von dir zu kaufen\", sagte David. \"Ich will Jahwe einen Altar bauen, damit die Seuche vom Volk abgewehrt wird.\"" },
      { number: 22, text: "Da sagte Arauna zu David: \"Mein Herr und König nehme und opfere, was er will. Hier sind die Rinder zum Brandopfer. Die Dreschschlitten und die Rindergeschirre können das Brennholz sein." },
      { number: 23, text: "Ich schenke dir das alles, mein König\", sagte Arauna und fügte hinzu: \"Möge Jahwe, dein Gott, dich gnädig annehmen!\"" },
      { number: 24, text: "\"Nein\", sagte der König, \"ich will es zum vollen Preis von dir kaufen. Ich will Jahwe, meinem Gott, keine kostenlosen Opfer bringen.\" So kaufte David den Platz und die Rinder für 50 Silberstücke." },
      { number: 25, text: "Er baute dort einen Altar für Jahwe und opferte Brand- und Freudenopfer*. Da ließ Jahwe sich für das Land erbitten und machte der Seuche in Israel ein Ende.", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
    ] },
  ],
};